/* Статьи и разборы для «Почитать»: паки, полные тексты, уроки (чистые данные) */
const READ_PACK=[
{id:'ford',topic:'biz',kind:'bio',t:'Генри Форд: как конвейер сделал машину дешевле лошади',min:3,src:'по открытым биографиям и истории Ford Motor Company',quote:'Думаешь, что можешь, или думаешь, что не можешь, — ты прав в обоих случаях.',
 body:['В 1903 году Генри Форд основал свою третью автомобильную компанию. Две предыдущие закончились ничем: первую закрыли инвесторы, из второй он ушёл сам. Ему было сорок, и в Детройте его считали упрямым механиком, который слишком долго возится с гоночными машинами вместо того, чтобы продавать обычные.',
 'В 1908 году вышла «Модель Т». Идея была простой и наглой: одна модель, минимум вариантов, цена, которую может потянуть рабочий. В 1913 году на заводе в Хайленд-Парке запустили движущийся сборочный конвейер: шасси, которое раньше собирали больше двенадцати часов, стали собирать примерно за полтора. Цена «Модели Т» падала почти каждый год — с 850 долларов на старте до менее 300 к середине двадцатых.',
 'В январе 1914 года Форд объявил, что будет платить рабочим пять долларов в день — примерно вдвое больше обычного. Конкуренты крутили пальцем у виска. Результат: очередь у заводских ворот, текучка упала, а рабочие Форда стали покупателями его же машин.'],
 take:['Одна вещь, сделанная дёшево и массово, бьёт десять сделанных дорого.','Плати тем, кто делает, больше рынка — вернётся лояльностью и качеством.','Третья попытка после двух провалов — нормальный путь, а не исключение.'],
 q:{t:'Что дал движущийся конвейер в 1913 году?',o:['Новый цвет кузова','Сборку шасси примерно за полтора часа вместо двенадцати','Пятидневную рабочую неделю'],a:1}},
{id:'shackleton',topic:'history',kind:'bio',t:'Шеклтон: как вернуть всех живыми, когда корабль раздавило льдом',min:3,src:'по дневникам экспедиции «Эндьюранс» 1914–1916',quote:'Трудности — это просто то, что нужно преодолеть.',
 body:['В январе 1915 года судно «Эндьюранс» Эрнеста Шеклтона вмёрзло в лёд моря Уэдделла, так и не дойдя до Антарктиды. Десять месяцев команда дрейфовала вместе со льдом, пока в ноябре корабль не раздавило. Двадцать восемь человек остались на льдине с тремя шлюпками.',
 'Шеклтон сменил цель экспедиции: не пересечь материк, а вернуть всех. Он держал распорядок дня, ровную еду и настроение — играли в футбол на льду, пели, спорили. В апреле 1916 года на шлюпках добрались до острова Элефант. Оттуда Шеклтон с пятью людьми прошёл на семиметровой шлюпке «Джеймс Кэрд» около 1 300 километров штормового океана до Южной Георгии — за шестнадцать дней.',
 'Высадившись не с той стороны острова, они пешком пересекли горы и ледники без карты и дошли до китобойной станции. Четыре попытки спасения спустя, 30 августа 1916 года, Шеклтон снял с острова Элефант оставшихся двадцать два человека. Погибших не было.'],
 take:['Когда план рухнул, меняй цель, а не людей: «вернуть всех» — ясно и достижимо.','Распорядок и настроение держат команду дольше, чем запасы.','Лидер идёт в самую опасную часть пути сам.'],
 q:{t:'Сколько человек из экипажа «Эндьюранс» вернулись живыми?',o:['Все двадцать восемь','Половина','Только шестеро со шлюпки'],a:0}},
{id:'honda',topic:'biz',kind:'bio',t:'Соитиро Хонда: мотор на велосипед и гонка на острове Мэн',min:3,src:'по открытым биографиям и истории Honda Motor',quote:'Успех — это 99 процентов неудач.',
 body:['Соитиро Хонда вырос в семье кузнеца и с детства возился с моторами. После войны, в 1946 году, он начал ставить на велосипеды маленькие армейские генераторные моторчики, которые скупал по дешёвке, — так появились первые «мотовелосипеды», и их расхватывали: бензин и транспорт были в дефиците.',
 'В 1948 году он основал Honda Motor. Партнёр Такэо Фудзисава взял на себя деньги и продажи, Хонда — инженерию. В 1958 году вышел Super Cub — лёгкий мопед с автоматическим сцеплением, на котором можно ехать в костюме. Он стал самым продаваемым моторным транспортом в истории: больше ста миллионов штук.',
 'В 1959 году малоизвестная японская фирма заявилась на гонки «Турист Трофи» на острове Мэн — самые престижные мотогонки мира. Через два года Honda заняла там первые пять мест в своём классе. Хонда говорил, что гонки — лучший способ учиться быстро: там ошибки видно сразу.'],
 take:['Начинай с того, что у тебя под рукой: списанный моторчик и велосипед.','Найди партнёра, который умеет то, чего не умеешь ты, и не лезь в его работу.','Иди туда, где ошибки видно сразу, — там быстрее всего учишься.'],
 q:{t:'Чем стал знаменит Honda Super Cub?',o:['Самым быстрым мотоциклом своего времени','Самым продаваемым моторным транспортом в истории','Первым электромопедом'],a:1}},
{id:'kamprad',topic:'biz',kind:'bio',t:'Ингвар Кампрад: стол без ножек, который изменил мебель',min:2,src:'по открытым биографиям и истории IKEA',quote:'Дорогие решения — признак посредственности.',
 body:['Ингвар Кампрад основал IKEA в 1943 году, в семнадцать лет, на ферме в шведской глубинке. Название — его инициалы плюс первые буквы фермы Эльмтарюд и деревни Агуннарюд. Сначала он торговал спичками, ручками и чулками по почте, потом добавил мебель местных мастерских.',
 'В 1956 году сотрудник Гиллис Лундгрен, пытаясь засунуть стол в багажник, открутил ему ножки. Из этого случая выросла главная идея компании: мебель в плоской упаковке, которую покупатель везёт и собирает сам. Доставка дешевле, склад меньше, цена ниже.',
 'Первый магазин открылся в Эльмхульте в 1958 году. Кампрад всю жизнь летал экономом, ездил на старой машине и требовал от менеджеров того же: экономия должна быть привычкой, а не кампанией.'],
 take:['Большие идеи часто начинаются с бытовой неловкости — заметь её.','Переложи часть работы на клиента, если взамен даёшь цену, которую он любит.','Экономия работает только как привычка руководителя, а не как лозунг.'],
 q:{t:'Откуда взялась идея плоской упаковки?',o:['Из военных ящиков','Сотрудник открутил ножки стола, чтобы увезти его в багажнике','Из японской мебели'],a:1}},
{id:'korolev',topic:'history',kind:'bio',t:'Сергей Королёв: человек, которого не называли по имени',min:3,src:'по открытым биографиям и истории космонавтики',quote:'Кто хочет работать — ищет средства, кто не хочет — причины.',
 body:['Сергей Королёв с юности строил планеры и ракеты, а в 1938 году был арестован по ложному обвинению, прошёл Колыму и выжил там едва ли не чудом. Потом работал в закрытом конструкторском бюро заключённых, где строили самолёты.',
 'После войны он возглавил создание ракет. Его Р-7 стала первой межконтинентальной ракетой и той самой, что 4 октября 1957 года вывела на орбиту первый спутник. 12 апреля 1961 года ракета Королёва подняла Юрия Гагарина — первого человека в космосе.',
 'При жизни его имя было засекречено: в газетах писали «Главный конструктор». Нобелевский комитет, по воспоминаниям, запрашивал имя создателя спутника — и не получил ответа. Страна узнала, кто такой Королёв, только из некролога в январе 1966 года.'],
 take:['Результат может быть громче имени: Королёва не знали, а спутник слышал весь мир.','После самого тяжёлого периода жизни бывает самая большая работа.','«Главный конструктор» — это роль, которую можно взять в любом деле: отвечать за всё целиком.'],
 q:{t:'Какое событие произошло 4 октября 1957 года?',o:['Полёт Гагарина','Запуск первого искусственного спутника Земли','Высадка на Луну'],a:1}},
{id:'konyukhov',topic:'history',kind:'bio',t:'Фёдор Конюхов: океан на вёслах и шар вокруг света',min:2,src:'по открытым источникам о путешествиях Ф. Конюхова',quote:'Нельзя ждать идеальной погоды. Её не бывает.',
 body:['Фёдор Конюхов родился в 1951 году в приазовском селе и с детства выходил в море с дедом. За жизнь он совершил несколько одиночных кругосветных плаваний под парусом, поднимался на высочайшие вершины всех континентов и в одиночку пересекал океаны на вёсельной лодке — Атлантику и Тихий океан.',
 'В июле 2016 года он облетел Землю на воздушном шаре за одиннадцать с небольшим дней, установив мировой рекорд скорости кругосветки на шаре. В гондоле он почти не спал, боролся с обледенением и кислородным голоданием на высоте выше восьми километров.',
 'Конюхов — священник и художник, и каждую экспедицию он называет не рекордом, а работой: подготовка годами, маршрут по дням, а дальше — выйти и делать, что бы ни было за бортом.'],
 take:['Подготовка — годы, путь — дни. Пропорция правильная.','Большое дело делается в одиночку ровно до момента старта; до него — команда.','Назови рекорд работой — и страх станет расписанием.'],
 q:{t:'Какой рекорд установил Конюхов в 2016 году?',o:['Самое быстрое пересечение Атлантики на вёслах','Самая быстрая кругосветка на воздушном шаре','Самый долгий одиночный поход на лыжах'],a:1}},
{id:'amundsen',topic:'history',kind:'hist',t:'Амундсен и Скотт: гонка к полюсу, которую выиграла подготовка',min:3,src:'по истории полярных экспедиций 1910–1912',
 body:['В 1911 году к Южному полюсу шли две экспедиции. Норвежец Руаль Амундсен сделал ставку на собак, лыжи и склады с едой, заложенные заранее через равные промежутки. Его люди всю жизнь ходили на лыжах, а собаки по ходу пути становились кормом для других собак — жестоко, но рассчитано.',
 'Англичанин Роберт Скотт взял мотосани, пони и людей, которые тянули сани сами. Мотосани сломались, пони погибли в холоде, и последние сотни километров команда тащила груз на себе.',
 'Амундсен достиг полюса 14 декабря 1911 года и вернулся без потерь. Скотт пришёл на пять недель позже, 17 января 1912-го, нашёл норвежскую палатку с флагом и на обратном пути погиб вместе со спутниками в одиннадцати милях от склада с едой.'],
 take:['Побеждает не тот, кто смелее, а тот, кто заранее заложил склады.','Используй то, в чём ты силён с детства, а не то, что выглядит современно.','Запас прочности считается до старта; в пути уже поздно.'],
 q:{t:'На что сделал ставку Амундсен?',o:['На мотосани и пони','На собак, лыжи и заранее заложенные склады','На помощь местных жителей'],a:1}},
{id:'magellan',topic:'history',kind:'hist',t:'Первая кругосветка: ушло пять кораблей, вернулся один',min:2,src:'по истории экспедиции 1519–1522 годов',
 body:['В сентябре 1519 года из Испании вышли пять кораблей Фернана Магеллана и около двухсот семидесяти человек. Задача — найти западный путь к Островам пряностей. Никто не знал, насколько велик океан, который позже назовут Тихим.',
 'За три года экспедиция пережила бунт, крушение, дезертирство одного корабля, голод, при котором ели кожу с рей, и гибель самого Магеллана в стычке на Филиппинах в апреле 1521 года.',
 'В сентябре 1522 года в Испанию вернулась одна «Виктория» под командованием Хуана Себастьяна Элькано — с восемнадцатью людьми на борту и грузом гвоздики, который окупил всю экспедицию. Земля оказалась круглой на практике, а не в книгах.'],
 take:['Большие маршруты редко проходит тот, кто их начал: готовь людей, которые дойдут.','Один вернувшийся корабль с правильным грузом окупает четыре потерянных.','Неизвестный размер задачи — главная причина брать запас, а не оптимизм.'],
 q:{t:'Сколько кораблей вернулось из первой кругосветки?',o:['Все пять','Три','Один'],a:2}},
{id:'bering',topic:'fleet',kind:'hist',t:'Беринг: экспедиция, которая нарисовала карту Сибири и Аляски',min:2,src:'по истории Великой Северной экспедиции 1733–1743',
 body:['Витус Беринг, датчанин на русской службе, возглавил самое большое научное предприятие XVIII века — Великую Северную экспедицию. Десять лет отряды описывали побережье Северного Ледовитого океана от Архангельска до Чукотки, а сам Беринг искал путь к Америке.',
 'В 1741 году его пакетбот «Святой Пётр» дошёл до побережья Аляски. На обратном пути корабль выбросило на необитаемый остров, где команда зимовала в землянках; Беринг умер там в декабре 1741-го. Остров и море теперь носят его имя.',
 'Выжившие построили из обломков новое судно и вернулись на Камчатку. Карты, промеры и описания экспедиции на сто лет вперёд стали основой навигации в этих водах.'],
 take:['Самая ценная добыча экспедиции — карты, а не трофеи.','Работа, сделанная «для отчёта», может служить сто лет.','Зимовка в землянке — тоже часть плана, если ты о ней подумал заранее.'],
 q:{t:'Чем закончилась для Беринга экспедиция 1741 года?',o:['Он вернулся в Петербург с наградой','Он умер на необитаемом острове, который назвали его именем','Он остался жить на Аляске'],a:1}},
{id:'lock',topic:'fleet',kind:'fact',t:'Как шлюз поднимает судно без единого насоса',min:2,src:'основы гидротехники',
 body:['Шлюз — это камера с воротами с двух сторон. Судно заходит, ворота закрываются, и камеру наполняют водой из верхнего бьефа через затворы в стенах или днище. Вода идёт сама, под действием тяжести: насосы не нужны, нужна только разница уровней.',
 'Когда вода в камере сравнялась с верхним уровнем, открывают верхние ворота — судно выходит на новую высоту. На спуск всё то же самое, только воду сбрасывают вниз. Один цикл занимает от десяти минут до получаса в зависимости от размера камеры.',
 'На Волго-Донском канале тринадцать шлюзов поднимают суда на восемьдесят восемь метров над Волгой и спускают на сорок четыре к Дону. Каждая шлюзовка — это сотни тысяч кубометров воды, которые уходят вниз навсегда, поэтому на водоразделе работают насосные станции, возвращающие воду наверх.'],
 take:['Самое надёжное — то, что работает на разнице уровней, а не на моторе.','Ворота открываются только тогда, когда давление с обеих сторон равно.','Большая система всегда где-то тихо возвращает ресурс наверх.'],
 q:{t:'За счёт чего вода заполняет камеру шлюза?',o:['За счёт насосов','За счёт разницы уровней и силы тяжести','За счёт винтов судна'],a:1}},
{id:'squat',topic:'fleet',kind:'fact',t:'Почему на мелководье судно садится глубже, когда идёт быстрее',min:2,src:'основы судовождения',
 body:['Когда судно движется, вода под днищем ускоряется, чтобы обойти корпус. Там, где скорость потока больше, давление меньше — и судно проседает. На глубокой воде это незаметно, а на мелководье поток зажат между днищем и дном, и просадка растёт резко.',
 'Это явление называют проседанием, или эффектом сквата. На скорости двенадцать узлов крупное судно может просесть на метр и больше, причём чаще кормой или носом в зависимости от формы корпуса. Запас воды под килём, который был на стоянке, в движении исчезает.',
 'Правило капитана простое: на мелководье сбавляй ход заранее, а не тогда, когда уже чувствуешь, что судно «тянет» к дну. Просадка падает примерно пропорционально квадрату скорости — половина скорости даёт четверть просадки.'],
 take:['Запас, который был на стоянке, в движении уменьшается — считай его заранее.','Половина скорости — четверть риска: сбавлять выгоднее, чем кажется.','Опасность часто не в глубине, а в скорости, с которой ты в неё заходишь.'],
 q:{t:'Как меняется просадка судна при снижении скорости вдвое?',o:['Уменьшается примерно вчетверо','Не меняется','Уменьшается вдвое'],a:0}},
{id:'antifouling',topic:'fleet',kind:'fact',t:'Зачем корпус ниже ватерлинии красят особой краской',min:2,src:'основы эксплуатации судов',
 body:['Через несколько недель в воде на корпусе поселяются водоросли, ракушки и бактериальная слизь. Шершавый корпус хуже скользит, расход топлива растёт на десятки процентов, скорость падает. Это называется обрастанием.',
 'Подводную часть красят необрастающей краской: она медленно отдаёт в воду вещества, которые не дают организмам закрепиться. Срок службы покрытия — от одного до нескольких сезонов, потом нужна докование, очистка и новый слой.',
 'В речной воде обрастание слабее, чем в тёплых морях, но ил, водоросли и ракушка-дрейссена всё равно делают своё дело. Чистый корпус — это не красота, а экономия топлива и ход.'],
 take:['Невидимая шершавость съедает ресурс так же, как явная поломка.','Профилактика раз в сезон дешевле борьбы с последствиями весь сезон.','То, что «как-то работает», обычно работает дороже, чем нужно.'],
 q:{t:'Чем грозит обрастание корпуса?',o:['Ростом расхода топлива и падением скорости','Только внешним видом','Коррозией палубы'],a:0}},
{id:'annuity',topic:'money',kind:'useful',t:'Аннуитет или дифференцированный: какой платёж выгоднее',min:3,src:'базовые правила кредитования; считается калькулятором в разделе «Дела»',
 body:['Аннуитетный платёж одинаковый каждый месяц. В начале срока почти весь он уходит на проценты, а тело долга уменьшается медленно. Дифференцированный платёж в начале больше, а потом снижается: тело долга гасится равными частями, а проценты начисляются на остаток.',
 'При одинаковой ставке и сроке переплата по дифференцированному платежу всегда меньше, потому что долг уменьшается быстрее. Но первые платежи тяжелее, и банк может не одобрить сумму, которую одобрит под аннуитет.',
 'Практическое правило: если платёж не давит — бери дифференцированный или досрочно гаси аннуитет в первые годы, когда проценты самые большие. Досрочный платёж в первый год срока экономит в разы больше, чем такой же в последний.'],
 take:['Проценты начисляются на остаток: чем раньше уменьшил долг, тем больше сэкономил.','Аннуитет удобен, дифференцированный выгоден — выбирай по запасу в бюджете.','Досрочное погашение в начале срока — самая выгодная инвестиция, какая у тебя есть.'],
 q:{t:'Когда досрочный платёж экономит больше всего?',o:['В конце срока','В первые годы срока','Без разницы'],a:1}},
{id:'cushion',topic:'money',kind:'useful',t:'Подушка безопасности: сколько и где держать',min:2,src:'общепринятые правила личных финансов',
 body:['Подушка — это деньги на жизнь без дохода. Ориентир для сменного графика и работы по контракту — расходы за три–шесть месяцев: аренда или ипотека, еда, кредиты, связь, минимум на транспорт. Не доход, а именно расходы.',
 'Держать её нужно там, откуда можно забрать за день без потерь: накопительный счёт или вклад с возможностью снятия. Не в акциях, не в наличных дома, не в «вот этот знакомый вернёт через месяц».',
 'Собирать проще всего автоматически: отдельный счёт и перевод в день зарплаты, пока деньги не разошлись. Начни с одного месяца расходов — это уже защищает от большинства неприятностей, а дальше копилка в приложении покажет, когда будет три.'],
 take:['Считай в месяцах расходов, а не в красивой сумме.','Деньги на чёрный день должны быть скучными и доступными.','Перевод в день зарплаты — единственный способ, который работает у всех.'],
 q:{t:'Где правильно держать подушку безопасности?',o:['В акциях','На накопительном счёте или вкладе с возможностью снятия','Наличными дома'],a:1}},
{id:'compound',topic:'money',kind:'useful',t:'Сложный процент: почему десять тысяч в месяц превращаются в два миллиона',min:2,src:'расчёт по формуле будущей стоимости аннуитета',
 body:['Если откладывать десять тысяч рублей в месяц под десять процентов годовых с ежемесячной капитализацией, через десять лет на счёте будет около двух миллионов — при том, что ты внёс только один миллион двести тысяч. Остальное заработали проценты на проценты.',
 'Фокус в том, что первые годы прирост почти незаметен, а последние дают больше всего: к концу десятого года проценты приносят больше, чем ты вносишь сам. Поэтому самое важное — начать раньше, а не выбрать идеальный инструмент.',
 'То же самое работает против тебя в кредитах: долг, который не гасится, растёт по той же кривой. Сложный процент не имеет мнения — он просто умножает то, что ты ему дал.'],
 take:['Начать на пять лет раньше важнее, чем найти ставку на два процента выше.','Ощущение «ничего не растёт» в первые годы — нормально, это часть формулы.','Та же кривая работает в кредите: не корми её.'],
 q:{t:'Сколько из двух миллионов в примере внёс сам человек?',o:['Около 1,2 миллиона','Весь два миллиона','Около 600 тысяч'],a:0}},
{id:'starlings',topic:'nature',kind:'fact',t:'Почему стая скворцов не сталкивается в воздухе',min:2,src:'исследования коллективного поведения птиц',
 body:['Осенью тысячи скворцов собираются в облако, которое переливается в небе, как одно существо. Ни одна птица не командует — и ни одна не врезается в соседку.',
 'Исследователи, снимавшие такие стаи несколькими камерами, выяснили: каждая птица следит примерно за семью ближайшими соседями, независимо от того, насколько близко они летят. Она повторяет их повороты с задержкой в доли секунды. Семь — достаточно, чтобы стая вела себя как целое, и мало, чтобы не перегружать мозг.',
 'Так сигнал о ястребе с края стаи за секунду доходит до противоположного края. Простое правило у каждого — и сложное поведение у всех. Экипаж работает так же: никто не видит всю картину, но каждый смотрит на своих.'],
 take:['Следи за семью ближайшими — и система будет работать как одно целое.','Простое правило для каждого сильнее сложного плана для всех.','Сигнал опасности передаётся через соседей, а не через начальника.'],
 q:{t:'За сколькими соседями следит скворец в стае?',o:['За всеми','Примерно за семью','За одним вожаком'],a:1}},
{id:'ice',topic:'nature',kind:'fact',t:'Почему лёд скользкий (и это не из-за давления)',min:2,src:'физика поверхности льда',
 body:['Школьное объяснение — «давление конька плавит лёд» — почти неверно: давления от ботинка хватило бы, чтобы понизить температуру плавления на сотые доли градуса. А скользко и при минус двадцати.',
 'На самом деле на поверхности льда всегда есть тонкий, в несколько молекул, подвижный слой — молекулам на самой кромке не за что держаться со всех сторон, и они ведут себя почти как жидкость. Эту догадку высказал ещё Фарадей в XIX веке, а подтвердили только современными приборами.',
 'Чем ближе к нулю, тем этот слой толще и тем скользче. При сильном морозе лёд становится «сухим» и шершавым — по нему тяжелее и ехать, и падать. Отсюда правило трапа на судне зимой: самое опасное — около нуля, а не в лютый мороз.'],
 take:['Привычное объяснение не всегда верное — проверяй на цифрах.','Самое опасное — не крайность, а «около нуля».','Поверхность ведёт себя не так, как толща: это касается не только льда.'],
 q:{t:'Из-за чего лёд скользкий?',o:['Из-за давления ботинка','Из-за подвижного слоя молекул на поверхности','Из-за соли в воде'],a:1}},
{id:'salmon',topic:'nature',kind:'fact',t:'Как лосось находит свою реку через тысячи километров',min:2,src:'ихтиология, исследования миграций лососёвых',
 body:['Лосось рождается в реке, уходит в океан на годы и возвращается нереститься в тот же ручей, где появился на свет. Ошибки редки.',
 'В океане он держит курс по магнитному полю Земли — рыба «запоминает» магнитную подпись места, где вышла в море. Подойдя к берегу, переключается на обоняние: в молодости река впечаталась в память запахом, и лосось идёт вверх по течению, выбирая на каждом разветвлении воду с «родным» составом.',
 'Плотина, изменившая запах воды, или заиленный приток сбивают навигацию — поэтому рыбоходы строят так, чтобы вода родной реки проходила через них. Два датчика, два масштаба: магнит — для океана, нос — для последних километров.'],
 take:['Большой маршрут — по компасу, последние километры — по знакомым приметам.','Запомненное в молодости ведёт через всю жизнь — выбирай, что запоминать.','Меняя среду, не сломай ориентиры тем, кто по ним возвращается.'],
 q:{t:'Что помогает лососю на последних километрах пути к родной реке?',o:['Зрение','Обоняние','Слух'],a:1}},
{id:'gps',topic:'science',kind:'fact',t:'Почему без Эйнштейна GPS врал бы на десять километров в день',min:2,src:'физика спутниковой навигации',
 body:['Приёмник GPS считает своё положение по времени прихода сигналов от спутников. Ошибка в наносекунды даёт ошибку в десятки сантиметров, поэтому на спутниках стоят атомные часы.',
 'Но часы на орбите идут не так, как на Земле. Из-за скорости спутника они отстают примерно на семь микросекунд в сутки, а из-за слабой гравитации на высоте двадцати тысяч километров — спешат примерно на сорок пять. Итого — около тридцати восьми микросекунд в сутки «лишних».',
 'Если бы это не учитывали, координаты уезжали бы примерно на десять километров каждый день. Поэтому часы спутников заранее настроены чуть медленнее. Теория, которую считают абстрактной, каждый день держит курс судна в створе.'],
 take:['Абстрактная теория — это то, что однажды становится частью прибора на мостике.','Систематическая ошибка страшнее случайной: она копится.','Калибруй заранее то, что знаешь, вместо того чтобы ловить ошибку потом.'],
 q:{t:'Что было бы с координатами GPS без поправок на относительность?',o:['Ничего не изменилось бы','Ошибка росла бы примерно на десять километров в день','Сигнал пропадал бы ночью'],a:1}},
{id:'echo',topic:'science',kind:'fact',t:'Эхолот: как судно видит дно звуком',min:2,src:'основы гидроакустики',
 body:['Эхолот посылает вниз короткий звуковой импульс и ждёт его отражения от дна. Звук в воде идёт примерно со скоростью полтора километра в секунду, поэтому глубина — это половина времени между импульсом и эхом, умноженная на скорость звука.',
 'Скорость звука в воде зависит от температуры, солёности и давления: в тёплой и солёной воде он быстрее. Хороший эхолот это учитывает, простой — считает по среднему, и на больших глубинах ошибка заметна.',
 'Тот же принцип у летучих мышей и дельфинов, которые различают эхом проволоку толщиной в волос. И у судового эхолота, который по форме эха отличает ил от камня: мягкое дно размазывает отражение, твёрдое — возвращает резкий сигнал.'],
 take:['Глубина — это время: измерь время точно, и получишь расстояние.','Прибор точен ровно настолько, насколько верны его допущения.','Форма ответа говорит больше, чем сам факт ответа.'],
 q:{t:'Что измеряет эхолот напрямую?',o:['Глубину','Время между импульсом и эхом','Плотность воды'],a:1}},
{id:'battery',topic:'science',kind:'useful',t:'Как продлить жизнь аккумулятору телефона в поездке',min:2,src:'инженерные рекомендации по литий-ионным аккумуляторам',
 body:['Литий-ионный аккумулятор стареет от двух вещей: от циклов и от времени при неудачных условиях. Хуже всего ему жарко и «под завязку»: долгое хранение при ста процентах и высокой температуре съедает ёмкость быстрее, чем сами зарядки.',
 'Практика: держать заряд между двадцатью и восьмьюдесятью процентами, не оставлять телефон на солнце или на горячей панели, заряжать понемногу, а не «до полного раз в сутки». Современные телефоны умеют ограничивать заряд восьмьюдесятью процентами — включи это, если не нужен полный запас.',
 'Мороз не убивает аккумулятор, но временно снижает ёмкость; заряжать на морозе — вредно. Выключение телефона на долгое хранение лучше делать при половине заряда, а не при нуле.'],
 take:['Жара и сто процентов — главные враги; циклы — второстепенные.','20–80 — удобный коридор, его можно включить в настройках.','Хранить — при половине заряда, заряжать — в тепле.'],
 q:{t:'Какое сочетание быстрее всего старит аккумулятор?',o:['Холод и половина заряда','Жара и полный заряд','Частые короткие подзарядки'],a:1}},
{id:'negatives',topic:'sport',kind:'useful',t:'Как сделать первое подтягивание: негативные повторения',min:2,src:'базовые принципы силовой подготовки с собственным весом',
 body:['Если подтянуться пока не получается, не надо «пытаться сильнее». Сила растёт от нагрузки, которую ты можешь выполнить, а не от той, что не можешь. Самый короткий путь — негативные повторения: залезь на перекладину с прыжка или с опоры и опускайся как можно медленнее, три–пять секунд.',
 'Схема: три подхода по пять медленных опусканий, через день. Второй инструмент — австралийские подтягивания с низкой перекладины или стола под углом, и резинка под колено, которая снимает часть веса.',
 'Через две–четыре недели негативов обычно появляется первое чистое подтягивание. Дальше — те же негативы и постепенное добавление повторений. Рекорд «на раз» на этом этапе не нужен, нужны ровные подходы.'],
 take:['Тренируй то, что можешь сделать, а не то, что хочешь сделать.','Медленное опускание — самая недооценённая работа в силовых.','Через день, три подхода, без рывков: программа на месяц уже есть.'],
 q:{t:'Что такое негативное повторение?',o:['Подтягивание с рывком','Медленное опускание из верхней точки','Вис на перекладине на время'],a:1}},
{id:'sleep',topic:'sport',kind:'useful',t:'Сон — это тренировка, которую ты пропускаешь',min:2,src:'физиология восстановления, общие рекомендации',
 body:['Мышцы растут не на тренировке, а после неё — во сне, когда идёт восстановление тканей и вырабатывается гормон роста. Семь–девять часов — норма для взрослого, и недосып напрямую бьёт по результатам: падает сила, точность, выносливость и растёт риск травмы.',
 'Сменный график ломает сон сильнее, чем кажется. Помогают постоянное время отбоя даже в выходные, тёмная и прохладная каюта, отказ от экрана за час до сна и от кофе после обеда. Короткий дневной сон до тридцати минут восстанавливает, длиннее — ломает ночь.',
 'Простое правило: если выбор между лишней тренировкой и лишним часом сна — выбирай сон. Тренировка на недосыпе даёт меньше, а стоит дороже.'],
 take:['Рост происходит во сне; тренировка — только запрос на него.','Постоянное время отбоя важнее идеальной длительности.','Дневной сон до тридцати минут — инструмент, дольше — вред.'],
 q:{t:'Какая длительность дневного сна помогает, а не мешает?',o:['До тридцати минут','Два часа','Любая'],a:0}},
{id:'return',topic:'home',kind:'useful',t:'Первые три дня дома после долгой поездки',min:2,src:'практика семей, где один часто в отъезде',
 body:['Пока тебя не было, дом жил по своим правилам: кто когда встаёт, кто моет посуду, где лежат ключи. Самая частая ошибка первых дней — прийти и «навести порядок». Для тех, кто держал дом, это звучит как «вы всё делали неправильно».',
 'Правило трёх дней: первые три дня ничего не перестраивать. Наблюдать, помогать там, где просят, и говорить спасибо за то, что всё работало без тебя. Хочешь что-то изменить — предложи на четвёртый день и спроси, удобно ли это им.',
 'С детьми — то же самое: не лавина подарков и не воспитание с порога, а время. Полчаса своего внимания каждый день первых трёх дней стоят больше, чем большой подарок. Сон после смены часовых поясов и сменного ритма тоже стоит планировать, а не «как получится».'],
 take:['Три дня — смотреть и помогать, на четвёртый — предлагать.','Благодарность за то, что дом работал без тебя, — первый разговор.','Время с детьми важнее подарка, особенно короткое и каждый день.'],
 q:{t:'Что советует правило трёх дней?',o:['Сразу навести свой порядок','Три дня не перестраивать, наблюдать и помогать','Уехать на рыбалку'],a:1}}
];
const READ_PACK2=[
{id:'kroc',topic:'biz',kind:'bio',t:'Рэй Крок: продавец миксеров, который в 52 года построил McDonald’s',min:3,src:'по открытым биографиям Рэя Крока и истории McDonald’s',quote:'Ничто в мире не заменит упорства.',
 body:['В 1954 году Рэй Крок продавал миксеры для молочных коктейлей и был не самым успешным коммивояжёром: ему было пятьдесят два, за спиной — работа тапёром, торговля бумажными стаканчиками и долги. Один маленький ресторан в Сан-Бернардино заказал у него сразу восемь миксеров. Крок поехал посмотреть, кому нужно сорок коктейлей одновременно.',
 'Ресторан братьев Макдональд работал как конвейер: меню из нескольких позиций, бургер за пятнадцать центов, очередь двигалась быстро, кухня была видна покупателям. Крок понял, что продавать надо не миксеры, а саму систему. В 1955 году он открыл первый ресторан по франшизе в Де-Плейнсе под Чикаго и настоял на одинаковых правилах для всех точек: те же продукты, то же время приготовления, та же чистота.',
 'В 1961 году он выкупил бизнес у братьев за 2,7 миллиона долларов — деньги занимал, компания едва сводила концы с концами. Сеть росла за счёт земли под ресторанами: компания сдавала её франчайзи в аренду, и это стало главным источником дохода. К его смерти в 1984 году ресторанов было больше семи тысяч.'],
 take:['Начинать в пятьдесят два — не поздно, если рядом оказалась работающая система.','Выигрывает не идея, а повторяемость: одинаковое качество в каждой точке.','Смотри, кто заказывает слишком много, — там спрятан настоящий бизнес.'],
 q:{t:'Что заставило Крока поехать в Сан-Бернардино?',o:['Приглашение братьев Макдональд','Заказ сразу на восемь миксеров от одного ресторана','Реклама в газете'],a:1}},
{id:'knight',topic:'biz',kind:'bio',t:'Фил Найт: кроссовки из багажника и логотип за 35 долларов',min:3,src:'по книге Фила Найта «Продавец обуви» и открытым источникам',quote:'Не останавливайся, пока не придёшь. И не думай слишком много о том, где это «пришёл».',
 body:['В 1964 году бухгалтер Фил Найт и его бывший тренер по бегу Билл Бауэрман скинулись по пятьсот долларов и основали Blue Ribbon Sports. Они ввозили японские кроссовки Onitsuka Tiger и продавали их с багажника машины на легкоатлетических соревнованиях. Найт при этом продолжал работать бухгалтером, потому что компания не приносила ему зарплаты.',
 'Бауэрман экспериментировал с подошвами и однажды залил резину в вафельницу жены — так появилась «вафельная» подошва, лёгкая и цепкая. В 1971 году партнёры поссорились с японским поставщиком и запустили собственный бренд. Логотип-галочку нарисовала студентка Кэролин Дэвидсон за тридцать пять долларов; позже компания подарила ей акции.',
 'Первые годы Nike жила в долг: банки отказывали, деньги приходили из японской торговой компании, и каждая партия обуви оплачивалась выручкой с предыдущей. Найт описывал это как бег, в котором нельзя остановиться. Компания вышла на биржу только в 1980 году — через шестнадцать лет после первых продаж с багажника.'],
 take:['Первые годы можно и нужно работать на две работы: бизнес и зарплата.','Ищи решения в подручных вещах — вафельница дала подошву на десятилетия.','Шестнадцать лет до биржи — нормальный срок, а не провал.'],
 q:{t:'Откуда взялась «вафельная» подошва?',o:['Из лаборатории японского поставщика','Бауэрман залил резину в домашнюю вафельницу','Её купили у конкурентов'],a:1}},
{id:'dyson',topic:'biz',kind:'bio',t:'Джеймс Дайсон: 5 127 прототипов до первого пылесоса',min:2,src:'по открытым интервью и биографии Джеймса Дайсона',
 body:['В 1978 году инженер Джеймс Дайсон разозлился на собственный пылесос: мешок забивался пылью, и тяга падала. На лесопилке он видел циклонный сепаратор, который отделяет опилки от воздуха центробежной силой, и решил сделать такой же, только размером с ведро.',
 'Следующие пять лет он собирал прототипы из картона и скотча в сарае за домом — по его подсчётам, 5 127 штук. Семья жила на зарплату жены-учительницы. Готовую технологию он предлагал крупным производителям, но те отказывались: продажа мешков была для них отдельным доходом.',
 'Первый пылесос Dyson продавался в Японии с 1986 года, а в Британии собственная модель DC01 вышла только в 1993-м — через пятнадцать лет после первой идеи. Через полтора года она стала самой продаваемой в стране. Дайсон до сих пор говорит, что каждый провальный прототип был не ошибкой, а измерением.'],
 take:['Прототип не обязан быть красивым: картон и скотч тоже считаются.','Крупные игроки откажут, если ты ломаешь их доход. Это не приговор идее.','Считай неудачи как измерения, а не как поражения.'],
 q:{t:'Где Дайсон подсмотрел идею циклона?',o:['На лесопилке — в сепараторе для опилок','В журнале о космосе','У конкурентов на выставке'],a:0}},
{id:'ortega',topic:'biz',kind:'bio',t:'Амансио Ортега: как магазин в провинции обогнал мировую моду',min:2,src:'по открытым источникам об истории Inditex',
 body:['Амансио Ортега бросил школу в четырнадцать и пошёл подмастерьем в магазин рубашек в Ла-Корунье, небольшом городе на северо-западе Испании. Там он понял простую вещь: между ценой ткани и ценой готового платья лежит огромная наценка посредников.',
 'В 1963 году он начал шить халаты и бельё у себя дома, а в 1975-м открыл первый магазин Zara. Главная идея была не в дизайне, а в скорости: пока у конкурентов коллекция готовилась полгода, у Ортеги путь от эскиза до витрины занимал две-три недели. Небольшие партии, частые поставки, фабрики рядом — то, что потом назовут «быстрой модой».',
 'Магазины сами стали разведкой: продавцы каждый день сообщали, что просили покупатели и что не брали, и фабрики меняли планы на ходу. Компания Inditex вышла на биржу в 2001 году, а Ортега, который почти не давал интервью и до семидесяти лет обедал в столовой с работниками, стал одним из самых богатых людей Европы.'],
 take:['Скорость — такое же преимущество, как цена и качество.','Самая точная аналитика — спросить продавца, что просили сегодня.','Можно построить гигантскую компанию, не переезжая из родного города.'],
 q:{t:'В чём была главная идея Zara?',o:['Самый дорогой дизайн','Две-три недели от эскиза до витрины вместо полугода','Только онлайн-продажи'],a:1}},
{id:'transsib',topic:'history',kind:'hist',t:'Транссиб: как за 25 лет построили самую длинную дорогу в мире',min:3,src:'по открытым историческим источникам о строительстве Транссибирской магистрали',
 body:['Решение строить железную дорогу через всю Сибирь приняли в 1891 году. Расстояние от Челябинска до Владивостока — около семи тысяч километров тайги, болот, вечной мерзлоты и больших рек. Денег в казне не хватало, инженеров с таким опытом не было ни у кого в мире.',
 'Дорогу вели одновременно с нескольких концов, чтобы выиграть время. Самые тяжёлые участки — мосты через Обь, Енисей и Амур, а также Кругобайкальская дорога: тридцать девять тоннелей на восьмидесяти четырёх километрах скал над озером. Пока её строили, поезда через Байкал перевозил паром-ледокол, а зимой рельсы клали прямо по льду.',
 'Сквозное движение по территории страны открылось в 1916 году, когда достроили мост через Амур у Хабаровска. Дорога окупилась не столько билетами, сколько тем, что вдоль неё за двадцать лет переселились миллионы людей и выросли города. Сегодня это по-прежнему самая длинная железная дорога в мире — больше девяти тысяч километров.'],
 take:['Большую задачу делят на участки и ведут параллельно.','Временное решение (паром, рельсы по льду) — нормально, пока строится постоянное.','Инфраструктура окупается не сразу и не напрямую.'],
 q:{t:'Как поезда пересекали Байкал, пока строили Кругобайкальскую дорогу?',o:['На пароме-ледоколе, зимой — по рельсам на льду','Объезжали озеро с севера','Никак, движение останавливали'],a:0}},
{id:'apollo13',topic:'history',kind:'hist',t:'«Аполлон-13»: как вернуть людей, когда взорвался кислородный бак',min:3,src:'по материалам NASA и открытым источникам',
 body:['В апреле 1970 года, на третьи сутки полёта к Луне, в служебном модуле «Аполлона-13» взорвался кислородный бак. Корабль потерял электричество, воду и большую часть кислорода. До Земли было больше трёхсот тысяч километров, и высадку отменили за минуты.',
 'Трое космонавтов перебрались в лунный модуль, рассчитанный на двоих и на двое суток, а лететь нужно было четверо. Главной проблемой стал углекислый газ: фильтры лунного модуля заканчивались, а фильтры командного имели другую форму. Инженеры на Земле собрали переходник из того, что было на борту, — картонной обложки, пластикового пакета, носка и скотча — и продиктовали инструкцию по радио.',
 'Чтобы сэкономить энергию, температуру в кабине опустили почти до нуля, воду выдавали по глотку. Траекторию для возвращения корректировали вручную, по положению Земли в иллюминаторе. 17 апреля капсула приводнилась в Тихом океане. Миссию называют самым успешным провалом в истории: цель не достигнута, все живы.'],
 take:['В кризисе сначала считают ресурсы: кислород, вода, энергия, время.','Решение из подручных вещей не хуже заводского, если работает.','Успех — это не всегда достижение цели. Иногда это все живы.'],
 q:{t:'Из чего собрали переходник для фильтра углекислого газа?',o:['Из запасных деталей, привезённых с Земли','Из обложки, пакета, носка и скотча','Его напечатали на борту'],a:1}},
{id:'wing',topic:'fleet',kind:'fact',t:'Почему самолёт держится в воздухе — и почему школьное объяснение неверно',min:2,src:'аэродинамика, базовые учебники',
 body:['Популярное объяснение звучит так: верх крыла выпуклый, воздуху приходится бежать по нему дольше, он разгоняется, давление падает — и крыло подсасывает вверх. Красиво, но неверно: воздух над крылом и под крылом не обязан встречаться в одной точке, а самолёты с плоским крылом и бумажные самолётики летают.',
 'Честное объяснение проще. Крыло поставлено под небольшим углом к потоку и отклоняет воздух вниз. По третьему закону Ньютона воздух толкает крыло вверх. Одновременно из-за формы и угла поток над крылом действительно ускоряется, и давление сверху становится меньше, чем снизу. Это две стороны одного явления, а не два разных.',
 'Подъёмная сила растёт с квадратом скорости и с углом атаки — до предела. Если задрать нос слишком сильно, поток отрывается от крыла, подъёмная сила резко падает — это сваливание. Поэтому на взлёте и посадке выпускают закрылки: они увеличивают кривизну и площадь крыла и позволяют лететь медленно, не сваливаясь.'],
 take:['«Воздух сверху бежит дольше» — миф. Крыло отбрасывает воздух вниз, и воздух толкает его вверх.','Сила растёт с квадратом скорости: вдвое быстрее — вчетверо сильнее.','У всего есть угол, после которого резко становится хуже.'],
 q:{t:'Что происходит при слишком большом угле атаки?',o:['Подъёмная сила бесконечно растёт','Поток отрывается, и сила падает — сваливание','Самолёт разгоняется'],a:1}},
{id:'tacoma',topic:'fleet',kind:'fact',t:'Мост, который сложил ветер: Такома, 1940',min:2,src:'инженерная история, отчёты о катастрофе Такомского моста',
 body:['Подвесной мост через пролив Такома в штате Вашингтон открыли в июле 1940 года. Он был узким и лёгким, с цельной балкой жёсткости вместо решётчатой фермы — так дешевле и красивее. Уже на стройке рабочие заметили, что пролёт качается на ветру, и прозвали мост «Галопирующей Герти».',
 'Седьмого ноября при ветре около девятнадцати метров в секунду пролёт начал не просто раскачиваться, а скручиваться: один край дороги поднимался, другой опускался, амплитуда доходила до нескольких метров. Через час мост обрушился. Люди успели уйти; погибла только собака, оставшаяся в машине.',
 'Причина — не резонанс от «шагов ветра», как часто пишут, а аэродинамический флаттер: сплошная балка, как плохое крыло, сама создавала вихри, которые подкачивали колебания. После Такомы все большие мосты стали продувать в аэродинамической трубе, а в балках делать продухи. Мост перестроили в 1950 году — и он стоит до сих пор.'],
 take:['Красиво и дёшево — не аргументы, если конструкция «галопирует» на испытаниях.','Самая опасная сила — та, которую система подкачивает сама.','Катастрофа без жертв всё равно меняет правила для всех.'],
 q:{t:'Что погубило Такомский мост?',o:['Землетрясение','Аэродинамический флаттер сплошной балки на ветру','Перегруз грузовиками'],a:1}},
{id:'pascal',topic:'fleet',kind:'fact',t:'Почему домкрат поднимает машину одной рукой',min:2,src:'закон Паскаля, школьная физика',
 body:['Гидравлический домкрат — это две трубки с жидкостью разного сечения, соединённые между собой. Нажимая на узкий поршень, ты создаёшь давление, и по закону Паскаля оно одинаково передаётся во все точки жидкости — в том числе под широкий поршень.',
 'Сила равна давлению, умноженному на площадь. Если широкий поршень в пятьдесят раз больше узкого по площади, та же самая жидкость давит на него в пятьдесят раз сильнее. Нажал с силой двадцать килограммов — получил тонну. Бесплатного ничего нет: узкий поршень придётся продавить в пятьдесят раз дальше, чем поднимется машина. Поэтому домкрат качают много раз.',
 'На том же законе работают тормоза автомобиля (педаль — узкий цилиндр, колодки — широкие), ковш экскаватора, кресло у стоматолога и пресс, который штампует кузова. Рычаг, блок и гидравлика — три способа обменять расстояние на силу, и все три используют один принцип.'],
 take:['Сила умножается на отношение площадей, а расстояние делится на него же.','В технике почти всё — обмен пути на усилие.','Понимая один закон, узнаёшь его в тормозах, ковше и кресле у врача.'],
 q:{t:'Чем платишь за выигрыш в силе у домкрата?',o:['Ничем, это бесплатно','Узкий поршень нужно продавить во столько же раз дальше','Жидкость нагревается и испаряется'],a:1}},
{id:'cloud',topic:'science',kind:'fact',t:'Сколько весит облако',min:2,src:'метеорология, оценка плотности кучевого облака',
 body:['Кучевое облако средних размеров — около километра в длину, ширину и высоту — содержит примерно полграмма воды в каждом кубическом метре. Умножаем на миллиард кубометров и получаем около пятисот тонн. Это примерно сто взрослых слонов, висящих над головой.',
 'Почему оно не падает? Потому что эти пятьсот тонн раздроблены на капли диаметром в сотые доли миллиметра. Такие капли падают медленнее сантиметра в секунду, а восходящие потоки тёплого воздуха под облаком поднимаются быстрее. Облако — не предмет, а процесс: капли внутри постоянно рождаются, падают, испаряются и снова конденсируются.',
 'Дождь начинается, когда капли сливаются до миллиметра и больше — тогда их скорость падения доходит до нескольких метров в секунду, и поток их уже не держит. Грозовое облако в десятки раз больше кучевого и может весить миллионы тонн; энергия, которая в нём запасена, сравнима с небольшой атомной бомбой.'],
 take:['Тонны могут висеть в воздухе, если раздроблены достаточно мелко.','Многие «вещи» на самом деле процессы: облако, пробка, очередь.','Дождь — это момент, когда мелкое объединяется в крупное.'],
 q:{t:'Почему облако не падает, хотя весит сотни тонн?',o:['Вода в нём легче воздуха','Капли слишком мелкие, и восходящий воздух их держит','Его держит ветер сбоку'],a:1}},
{id:'sky',topic:'science',kind:'fact',t:'Почему небо синее, а закат красный',min:2,src:'оптика, рассеяние Рэлея',
 body:['Солнечный свет белый — в нём смешаны все цвета. Проходя через воздух, он рассеивается на молекулах газов, и короткие волны (синие и фиолетовые) рассеиваются гораздо сильнее длинных (красных): примерно в обратной четвёртой степени от длины волны. Синий свет разлетается по всему небу и приходит к глазу со всех сторон.',
 'Фиолетового в небе тоже много, но Солнце излучает его меньше, часть поглощается в верхних слоях, а глаз чувствительнее к синему. Поэтому мы видим голубой, а не фиолетовый. В космосе рассеивать нечего — небо там чёрное даже днём.',
 'На закате свет идёт к тебе сквозь толщу воздуха в десятки раз большую, чем в полдень. Синий по дороге рассеивается в стороны и до тебя не доходит, остаются жёлтый, оранжевый и красный. Пыль и дым после пожаров делают закаты ещё краснее — по той же причине.'],
 take:['Небо синее не потому, что воздух синий, а потому что он рассеивает синий.','Один закон объясняет и день, и закат, и чёрное небо в космосе.','Длинный путь оставляет только самое стойкое.'],
 q:{t:'Почему закат красный?',o:['Солнце остывает к вечеру','Синий рассеивается по длинному пути, остаётся красный','Воздух вечером краснеет от пыли'],a:1}},
{id:'ants',topic:'nature',kind:'fact',t:'Как муравьи находят кратчайший путь без карты и без начальника',min:2,src:'этология, исследования феромонных троп',
 body:['Муравей-разведчик ползёт случайно, и, найдя еду, возвращается домой, оставляя след из феромона. Другие муравьи натыкаются на след и идут по нему, тоже оставляя феромон. Чем больше муравьёв прошло, тем сильнее пахнет тропа — и тем больше муравьёв её выбирает.',
 'Если к еде ведут два пути, короткий и длинный, по короткому муравьи успевают пройти туда-обратно чаще. За то же время на нём откладывается больше феромона, а на длинном запах испаряется быстрее, чем обновляется. Через несколько минут вся колония ходит по короткому пути, хотя ни один муравей не сравнивал маршруты.',
 'Этот механизм — положительная обратная связь плюс испарение — скопировали программисты: «муравьиные алгоритмы» прокладывают маршруты для грузовиков и трафик в сетях. У колонии нет начальника и карты, но есть простое правило для каждого и забывание старого.'],
 take:['Сложное поведение группы складывается из простого правила для каждого.','Забывать старые пути так же важно, как прокладывать новые.','Чаще повторяемое укрепляется само — это работает и с привычками.'],
 q:{t:'Почему колония выбирает короткий путь?',o:['Разведчик измеряет оба и докладывает','На коротком феромон обновляется чаще, чем испаряется','Муравьи видят еду издалека'],a:1}},
{id:'frigate',topic:'nature',kind:'fact',t:'Птицы, которые спят в полёте',min:2,src:'исследование сна фрегатов (Ратенборг и др., 2016)',
 body:['Фрегаты — крупные морские птицы, которые могут не садиться неделями: садиться на воду они не умеют, перья намокают. Долго думали, что они вообще не спят в таких перелётах. В 2016 году учёные закрепили на фрегатах миниатюрные датчики активности мозга и записали, что происходит на самом деле.',
 'Оказалось, птицы спят в полёте, но очень мало — в среднем меньше часа в сутки, короткими отрезками по несколько секунд или минут, в основном когда набирают высоту в восходящем потоке. Чаще всего спит одно полушарие, а второе бодрствует и следит за курсом; иногда засыпают оба сразу, и птица продолжает планировать.',
 'На суше те же фрегаты спят по двенадцать часов. Значит, недосып в полёте — не норма, а долг, который возвращают на берегу. Такой «половинный» сон есть у дельфинов и уток на краю стаи: природа давно умеет совмещать отдых и дежурство.'],
 take:['Спать «одним полушарием» можно, но это долг, который придётся вернуть.','Коротких отрезков отдыха хватает только на время, не навсегда.','Самые интересные открытия ждут там, где все уверены, что «и так понятно».'],
 q:{t:'Сколько фрегаты спят в длительном полёте?',o:['Вообще не спят','Меньше часа в сутки, короткими отрезками','Как на суше, по двенадцать часов'],a:1}},
{id:'rule50',topic:'money',kind:'useful',t:'Правило 50/30/20: бюджет, который не надо вести',min:2,src:'популярная модель бюджета, описана Э. Уоррен',
 body:['Большинство бюджетов умирают через две недели, потому что требуют записывать каждую покупку. Правило 50/30/20 проще: половина дохода — на обязательное (жильё, еда, транспорт, связь, кредиты), тридцать процентов — на желания (кафе, подписки, одежда сверх нужного), двадцать — на будущее (подушка, долги сверх минимума, накопления).',
 'Главное действие одно: в день получки сразу перевести двадцать процентов на отдельный счёт, до всех трат. Не «что останется», а первым платежом себе. Остальное можно тратить, не считая, — лимит уже защищён.',
 'Если обязательное съедает больше половины, это сигнал, а не повод отказаться от правила: значит, жильё или кредит слишком дороги для текущего дохода. Пропорции можно сдвигать (60/20/20 на старте), но доля «на будущее» не должна опускаться ниже десяти — иначе подушка не появится никогда.'],
 take:['Платёж себе — первый, а не «что останется».','Записывать каждую покупку не нужно: нужна одна проводка в день получки.','Если «обязательное» больше половины — проблема в расходах, а не в бюджете.'],
 q:{t:'Что делать в день получки по правилу 50/30/20?',o:['Сначала оплатить желания','Сразу перевести 20% на отдельный счёт','Записать все будущие траты'],a:1}},
{id:'grace',topic:'money',kind:'useful',t:'Льготный период по кредитке: где прячется подвох',min:2,src:'условия российских банков, общие правила',
 body:['«До 120 дней без процентов» не значит, что любая покупка даёт четыре месяца. Период обычно считается от начала расчётного периода, а не от дня покупки: купил в последний день месяца — получил на тридцать дней меньше. Точную дату, до которой нужно вернуть всю сумму, смотри в приложении банка, а не в рекламе.',
 'Второй подвох — минимальный платёж. Если внести только его, льготный период на весь долг сгорает, и проценты начисляются со дня покупки по ставке в двадцать–сорок процентов годовых. Чтобы было бесплатно, возвращать нужно всю сумму целиком.',
 'Снятие наличных и переводы почти всегда вне льготного периода и с комиссией. Безопасный режим: платить картой только то, на что деньги уже есть на другом счёте, и гасить полностью в день, который показывает приложение. Тогда кредитка — это бесплатная отсрочка и кэшбэк, а не долг.'],
 take:['Период считается не от покупки, а от расчётной даты — смотри приложение.','Минимальный платёж убивает льготу: гасить нужно всё.','Наличные с кредитки — почти всегда проценты и комиссия.'],
 q:{t:'Что произойдёт, если внести только минимальный платёж?',o:['Ничего, льгота сохранится','Льгота сгорит, проценты начислят со дня покупки','Банк закроет карту'],a:1}},
{id:'inflation',topic:'money',kind:'useful',t:'Правило 72: за сколько лет деньги под матрасом потеряют половину',min:2,src:'правило 72, арифметика сложного процента',
 body:['Правило 72 — быстрый счёт в уме: раздели 72 на годовой процент и получишь, за сколько лет сумма удвоится. Вклад под 12% удваивается примерно за шесть лет, под 6% — за двенадцать. Работает и в обратную сторону: при инфляции 8% в год наличные теряют половину покупательной силы примерно за девять лет.',
 'Отсюда простой вывод: деньги, которые лежат больше нескольких месяцев, должны хотя бы догонять инфляцию. Подушка на три–шесть месяцев расходов — на вкладе или накопительном счёте с возможностью снять; всё, что сверх, — туда, где ставка выше инфляции, пусть и с ограничениями.',
 'Правило работает на длинных сроках и не заменяет калькулятор, но для решения «оставить дома или положить» точности хватает. Проверь: сколько денег у тебя лежит без процентов и за сколько лет они потеряют половину при текущей инфляции.'],
 take:['72 ÷ процент = годы до удвоения (или до потери половины).','Подушка — на счёте со снятием; остальное — выше инфляции.','Наличные дома дешевеют каждый день, даже если лежат нетронутыми.'],
 q:{t:'За сколько лет удвоится вклад под 9% годовых по правилу 72?',o:['Около 4 лет','Около 8 лет','Около 16 лет'],a:1}},
{id:'terry',topic:'sport',kind:'bio',t:'Терри Фокс: марафон каждый день на одной ноге',min:3,src:'по открытым источникам о «Марафоне надежды», 1980',
 body:['В восемнадцать лет канадцу Терри Фоксу ампутировали ногу выше колена из-за рака кости. В больнице он насмотрелся на детей в онкологии и решил пробежать через всю Канаду на протезе, чтобы собрать деньги на исследования. Он тренировался четырнадцать месяцев, скрывая от семьи, сколько это стоит ему боли.',
 'Двенадцатого апреля 1980 года он окунул протез в Атлантический океан в Ньюфаундленде и побежал на запад. Каждый день — около сорока двух километров, то есть марафон, при любой погоде. Первые недели о нём никто не знал; к Онтарио его встречали толпы, а пожертвования шли миллионами.',
 'На сто сорок третий день, пробежав больше пяти тысяч трёхсот километров, он остановился: рак дал метастазы в лёгкие. Через десять месяцев его не стало. Собрать «по доллару с каждого канадца» — его цель — удалось ещё при его жизни, а ежегодный забег его имени с тех пор собрал сотни миллионов.'],
 take:['Марафон в день — это не про спорт, а про решение, принятое один раз.','Первые недели никто не замечает. Это не повод останавливаться.','Цель, сформулированная цифрой («доллар с каждого»), понятна всем.'],
 q:{t:'Сколько Терри Фокс пробегал в день?',o:['Около 10 км','Около 42 км — марафон','Около 100 км'],a:1}},
{id:'pushups',topic:'sport',kind:'useful',t:'От десяти отжиманий к пятидесяти: метод, который не выматывает',min:2,src:'метод «смазки дорожки» (grease the groove), практика тренеров',
 body:['Самая частая ошибка — делать максимум до отказа каждый день. Мышцы не успевают восстановиться, техника ломается, прогресс встаёт на третьей неделе. Работает другое: много подходов за день, но каждый — на половину максимума, без усталости.',
 'Узнай свой максимум с хорошей техникой — скажем, двенадцать. Весь день делай подходы по шесть: утром, перед обедом, после работы, вечером — пять-шесть подходов, между ними часы. Ты никогда не устаёшь, но за день набираешь тридцать–сорок качественных повторений, а нервная система учится движению, как ходьбе.',
 'Раз в неделю проверяй максимум. Когда он вырос — поднимай рабочий подход до половины нового. Два дня в неделю отдыхай полностью. Обычно от десяти до тридцати уходит около двух месяцев, до пятидесяти — ещё три-четыре. Записывай каждый подход: цифры мотивируют сильнее, чем самочувствие.'],
 take:['Половина максимума много раз в день — лучше, чем один раз до отказа.','Проверять максимум — раз в неделю, не чаще.','Два полных дня отдыха в неделю — часть программы, а не слабость.'],
 q:{t:'Сколько повторений делать в рабочем подходе по этому методу?',o:['До отказа','Примерно половину максимума','Ровно десять, всегда'],a:1}},
{id:'talktest',topic:'sport',kind:'useful',t:'Бег для начинающих: правило разговора и правило десяти процентов',min:2,src:'рекомендации тренеров по бегу для начинающих',
 body:['Большинство бросает бег через месяц, потому что бегает слишком быстро. Простая проверка темпа — говорить полными фразами на бегу. Если можешь — темп правильный, это лёгкий бег, на котором растёт выносливость. Если хватает только на отдельные слова — сбавь или перейди на шаг.',
 'Первые недели чередуй: минута бега — две минуты шага, пятнадцать–двадцать минут всего, три раза в неделю. Каждую неделю прибавляй бега и убавляй шага. Через шесть–восемь недель большинство людей бежит полчаса без остановки — и без геройства.',
 'Второе правило — не прибавлять больше десяти процентов недельного объёма за раз. Колени, стопы и связки адаптируются медленнее, чем сердце и лёгкие, и травмы приходят именно от скачков. Обувь — беговая, по размеру, менять раз в шестьсот–восемьсот километров.'],
 take:['Можешь говорить фразами — темп правильный.','Чередование бега и шага — не позор, а программа.','Плюс десять процентов в неделю, не больше: связки медленнее сердца.'],
 q:{t:'Как понять, что темп правильный?',o:['Пульс должен зашкаливать','Можешь говорить полными фразами','Должно быть тяжело дышать'],a:1}},
{id:'quarrel',topic:'home',kind:'useful',t:'Правило двадцати минут: как не наговорить лишнего в ссоре',min:2,src:'исследования Дж. Готтмана о физиологии конфликта',
 body:['Когда ссора разгоняется, пульс поднимается выше ста ударов, и мозг переключается в режим «бей или беги». В этом состоянии человек физически не способен слушать и подбирать слова: он защищается. Продолжать разговор бесполезно — каждая фраза только добавляет дров.',
 'Рабочее правило: заметил, что голос поднялся, а аргументы кончились, — скажи об этом прямо и возьми паузу минимум на двадцать минут. Не хлопнуть дверью, а именно договориться: «Я завёлся, давай через полчаса». За это время пульс возвращается к норме, и разговор можно продолжить уже о деле.',
 'Паузу нельзя тратить на прокручивание обид — это разогревает заново. Пройтись, помыть посуду, подышать. И обязательно вернуться к разговору в обещанное время: пауза без возвращения выглядит как бегство и подрывает доверие сильнее самой ссоры.'],
 take:['Пульс выше ста — говорить бесполезно, можно только навредить.','Пауза объявляется словами и со сроком, а не дверью.','Вернуться вовремя важнее, чем победить в споре.'],
 q:{t:'Что главное в паузе во время ссоры?',o:['Уйти молча','Назвать срок и вернуться вовремя','Продумать за это время лучшие аргументы'],a:1}},
{id:'gifts',topic:'home',kind:'useful',t:'Подарки без паники: список, который собирается сам',min:2,src:'практика планирования, общие советы',
 body:['Лучшие подарки — это не те, что куплены за день до даты, а те, о которых человек сам обмолвился месяц назад. Заведи заметку на телефоне на каждого близкого и записывай туда всё, что слышишь: «хочу нормальный термос», «надо заменить наушники», «давно не был на рыбалке».',
 'Второе — календарь дат с напоминанием за две недели, не за день. Две недели — это время заказать, дождаться доставки и не переплатить за срочность. В «Самплане» для этого есть раздел «Важные даты»; подойдёт и обычный календарь.',
 'Третье — бюджет на подарки отдельной строкой: сумма на год делится на двенадцать и откладывается ежемесячно. Тогда декабрь с его тремя днями рождения и Новым годом не выбивает из колеи, а подарок выбирают по человеку, а не по остатку на карте.'],
 take:['Записывай оговорки близких — это готовый список подарков.','Напоминание за две недели, а не за день.','Подарки — отдельная строка бюджета, по двенадцатой части в месяц.'],
 q:{t:'За сколько ставить напоминание о дате?',o:['За день','За две недели','За два месяца'],a:1}},
{id:'parents',topic:'home',kind:'useful',t:'Звонок родителям: три вопроса, после которых есть о чём говорить',min:2,src:'практические советы по общению, общий опыт',
 body:['Обычный звонок родителям умирает на втором вопросе: «Как дела? — Нормально. — Ну ладно». Проблема не в том, что говорить не о чем, а в том, что вопрос слишком общий. Конкретный вопрос вытягивает рассказ: «Что сегодня готовила?», «Сосед починил машину?», «Что врач сказал про давление?».',
 'Второй приём — спрашивать про прошлое. Родители охотно рассказывают, как сами были в твоём возрасте, как познакомились, как переезжали. Эти истории всё равно уйдут, если их не спросить сейчас. Один вопрос в неделю — и через год у тебя семейная история, которую не знает никто, кроме тебя.',
 'Третье — рассказывать самому, не дожидаясь вопросов: одно конкретное событие за день, одна мелочь. Родителям нужны не отчёты, а ощущение, что они в курсе. Пять минут два раза в неделю по расписанию работают лучше, чем часовой разговор раз в месяц, когда уже накопилась вина.'],
 take:['Общий вопрос даёт «нормально». Конкретный даёт рассказ.','Спрашивай про их прошлое — потом будет поздно.','Коротко и регулярно лучше, чем долго и с чувством вины.'],
 q:{t:'Какой вопрос скорее вытянет рассказ?',o:['«Как дела?»','«Что врач сказал про давление?»','«Всё нормально?»'],a:1}}
];
