const READ_FULL={
ford:[['Провалы перед успехом','Первая компания Форда за пару лет выпустила лишь несколько дорогих и ненадёжных машин и закрылась. Во второй инвесторы хотели роскошных автомобилей, а Форд — гоночных и дешёвых; он ушёл, а компания позже стала Cadillac. Гонки Форд использовал как рекламу: победа его машины в 1901 году помогла найти деньги на третью попытку.'],
 ['Конвейер — это не только лента','Идею движущейся линии Форд и его инженеры подсмотрели на чикагских бойнях, где туши двигались от рабочего к рабочему. Но главным были взаимозаменяемые детали и разбиение работы на простые операции. Рабочему не нужно было уметь собрать машину — достаточно хорошо делать одно движение.'],
 ['Обратная сторона','Работа на конвейере была монотонной, люди уходили толпами — поэтому и понадобились пять долларов в день. А упрямство, которое помогло создать «Модель Т», потом сыграло против Форда: он слишком долго не хотел менять устаревшую модель, и в двадцатых конкуренты с выбором цветов и моделей обогнали его по продажам.']],
shackleton:[['Как он выбирал людей','Шеклтон набирал команду не только по опыту, но и по характеру: ему было важно, умеет ли человек сохранять спокойствие и ладить с другими. Учёные на борту мыли палубу наравне с матросами. Во льдах это окупилось: люди разных профессий привыкли делать любую работу.'],
 ['Распорядок против страха','На льдине у каждого были обязанности: охота на тюленей, починка снаряжения, дежурства. Шеклтон держал рядом с собой тех, кто легче поддавался унынию или мог устроить раскол. Самые тёплые спальные мешки из оленьего меха разыграли так, что они достались матросам, а Шеклтон и офицеры спали в шерстяных.'],
 ['Последний рывок','На Южной Георгии Шеклтон, Уорсли и Крин шли через горы около тридцати шести часов почти без остановок — с верёвкой и плотницким тесаком вместо ледоруба, с шурупами, вкрученными в подошвы. Потом Шеклтон не отдыхал: искал судно для спасения оставшихся и добился своего с четвёртой попытки.']],
honda:[['Неудачи по дороге','До своей компании Соитиро пробовал делать поршневые кольца для Toyota. Первые образцы почти все забраковали, и он пошёл учиться в технический институт, чтобы разобраться в металлургии. Потом его завод пострадал от бомбёжек и землетрясения. Каждая неудача добавляла знаний, которые пригодились позже.'],
 ['Партнёрство','Хонда был гениальным инженером, но плохо считал деньги. Фудзисава построил сеть продаж: разослал письма десяткам тысяч владельцев велосипедных лавок и предложил им продавать моторы. Разделение «инженер делает, партнёр продаёт» позволило компании расти, не отвлекая Хонду от мастерской.'],
 ['Super Cub в Америке','В США Honda сначала пыталась продавать большие мотоциклы, и они ломались на длинных дорогах. Сотрудники ездили по Лос-Анджелесу на своих маленьких Super Cub, и прохожие спрашивали, где такие купить. Компания переключилась на мопеды, а реклама «Самых приятных людей вы встретите на Honda» изменила образ мотоциклиста.']],
kamprad:[['Экономия как стиль','Кампрад считал расточительство грехом и сам подавал пример: торговался на рынках, носил старую одежду, летал экономом. Он объяснял это не жадностью, а уважением к деньгам покупателей: каждая лишняя крона расходов в итоге оказывается в цене товара.'],
 ['Самообслуживание','Магазины IKEA устроены так, что покупатель сам проходит маршрут, сам берёт коробки со склада и сам везёт их домой. Это экономит на продавцах и грузчиках. А ресторан в магазине появился, чтобы голодные покупатели не уходили раньше времени.'],
 ['Имена вместо артикулов','Названия товаров IKEA — шведские слова и названия мест. Кампрад страдал дислексией, и ему было проще запоминать имена, чем номера из цифр. Так появилась целая система: у кроватей, диванов и ковров — свои «семейства» имён.']],
korolev:[['Ранние годы','Королёв вырос в Житомире и Одессе, учился в Киеве и Москве, в юности строил планеры. В 1933 году вместе с энтузиастами из группы ГИРД он запустил одну из первых советских ракет на жидком топливе — ГИРД-09. Подъём на несколько сотен метров казался тогда огромным успехом.'],
 ['Колыма и шарашка','После ареста Королёв работал на золотом прииске Мальдяк на Колыме. Дело отправили на пересмотр, и он попал в закрытое бюро, где работал под началом Андрея Туполева, тоже арестованного. Позже в Казани он занимался ракетными ускорителями для самолётов.'],
 ['Как он руководил','Королёв был требовательным и сам работал без выходных. Его называли Главным; он умел собрать вокруг одной задачи десятки конструкторских бюро и заводов. Это умение договориться и заставить сотни людей работать как один механизм было не меньшим достижением, чем сами ракеты.']],
konyukhov:[['Подготовка','Перед каждой экспедицией Конюхов месяцами тренируется и продумывает маршрут вместе с командой на берегу. В одиночных переходах он держит распорядок: сон короткими отрезками, еда по часам, ежедневные записи. Дневники и рисунки из экспедиций потом становятся книгами и картинами.'],
 ['Один в океане','В одиночном переходе на вёсельной лодке главная опасность — не шторм, а усталость и одиночество. Помогает не считать оставшиеся мили, а делать работу на сегодня: грести положенные часы, следить за лодкой, есть и спать. Огромное расстояние превращается в последовательность обычных дней.'],
 ['Что взять себе','История Конюхова не о том, что всем надо пересекать океаны. Она о том, что любую большую цель можно разбить на дни и спокойно делать свою часть каждый день — даже если цель называется «сто отжиманий» или «первая пробежка без остановки».']],
amundsen:[['Учиться у тех, кто там живёт','До полюса Амундсен прошёл Северо-Западным проходом и зимовал рядом с инуитами. Он учился у них шить меховую одежду, строить укрытия из снега и управлять собачьими упряжками. Скотт полагался на опыт британского флота, Амундсен — на опыт людей, которые живут во льдах веками.'],
 ['Склады и метки','Склады с едой Амундсен отмечал флажками не только в точке, но и поперёк маршрута — линией на несколько километров в обе стороны. Даже если в метель отряд сбивался с курса, он упирался в эту линию и находил склад. Мелочь, которая спасает жизнь.'],
 ['Ритм','Норвежцы проходили в день примерно одно и то же расстояние — около тридцати километров — и останавливались, даже если оставались силы. Отдыхали и люди, и собаки. В плохую погоду тоже шли, но не больше нормы. Ровный ритм оказался надёжнее рывков.']],
magellan:[['Пролив','Самым трудным было найти проход из Атлантики в другой океан. Корабли месяцами шли вдоль берегов Южной Америки, заходя в каждый залив. Найденный в октябре 1520 года пролив, позже названный Магеллановым, проходили больше месяца — среди скал, течений и холодных ветров.'],
 ['Самый большой океан','Выйдя в спокойные воды, Магеллан назвал океан Тихим. Он думал, что до Островов пряностей несколько дней пути, а плыли больше трёх месяцев, не встречая обитаемой земли. Цинга косила людей: свежей еды не было, вода протухла, ели сухари с червями.'],
 ['Элькано','После гибели Магеллана экспедицию вёл баск Хуан Себастьян Элькано. Чтобы не попасть к португальцам, он провёл «Викторию» вокруг Африки, избегая портов, и потерял ещё много людей от голода. В его герб добавили глобус с надписью «Ты первым обошёл меня».']],
bering:[['Первая экспедиция','Ещё в 1728 году, по замыслу Петра Первого, Беринг прошёл от Камчатки на север через пролив между Азией и Америкой, но из-за тумана не увидел американского берега. Пролив позже назовут его именем. Вторая экспедиция должна была ответить на вопрос окончательно.'],
 ['Стеллер','На борту «Святого Петра» был натуралист Георг Стеллер. Он лечил команду травами и свежей едой и описал животных, которых потом никто не видел живыми, — например, морскую корову, истреблённую меньше чем за тридцать лет после экспедиции.'],
 ['Масштаб','В Великой Северной экспедиции участвовали тысячи человек, а отряды работали десять лет. Описать почти всё северное побережье Евразии — задача, сравнимая для своего времени с полётом в космос. Многие участники погибли, но карта осталась.']],
lock:[['Самые известные шлюзы','Шлюзы Панамского канала поднимают суда на 26 метров к искусственному озеру Гатун и опускают обратно к океану. Новые камеры, открытые в 2016 году, пропускают суда длиной до 366 метров и экономят воду: часть её уходит в боковые бассейны и используется снова.'],
 ['Как не разбить судно','Наполнение камеры — деликатный процесс. Если пустить воду слишком быстро, возникают течения и волны, которые раскачивают судно и бьют его о стенки. Поэтому вода заходит через систему галерей в днище, равномерно, а судно держат на швартовах.'],
 ['Шлюз в жизни','Шлюз — хорошая модель для любых больших перемен: подняться можно не одним прыжком, а ступенями, каждая из которых безопасна. Сделал шаг, выровнял уровень — открыл следующие ворота.']],
squat:[['Где это опасно','Сильнее всего проседание проявляется в узких каналах и на мелких фарватерах, где воде некуда уходить. Поэтому в каналах вводят ограничения скорости — дело не только в волне от судна, но и в запасе под килём.'],
 ['Эффект берега','У стенки канала возникает и боковой эффект: вода между бортом и берегом ускоряется, давление падает, и корму тянет к берегу, а нос отталкивает. Рулевому приходится заранее компенсировать это рулём.'],
 ['Тот же закон вокруг нас','Быстрый поток — низкое давление: поэтому велосипедиста подтягивает к проносящемуся мимо грузовику, а сильный ветер может сорвать крышу — снаружи поток быстрый и давление ниже, а внутри дома оно прежнее.']],
antifouling:[['Как было раньше','Деревянные корабли обшивали медными листами: медь ядовита для моллюсков и водорослей. Это давало флоту заметное преимущество в скорости. Отсюда английское выражение «с медным дном» — то есть надёжный.'],
 ['Экология','Долгое время в краски добавляли соединения олова — очень эффективные и очень ядовитые, они вредили устрицам и другим животным. Их запретили международной конвенцией, и сейчас используют более мягкие медные составы и гладкие силиконовые покрытия, к которым организмам трудно прилипнуть.'],
 ['Бытовая аналогия','Обрастание бывает и у людей: привычки, мелкие подписки, лишние вещи постепенно замедляют ход. Раз в сезон полезно устроить себе ремонт: отменить ненужное, разобрать завалы, вернуть лёгкость.']],
annuity:[['Пример на цифрах','Кредит 1 миллион на 5 лет под 20 % годовых. Аннуитет — около 26,5 тысячи в месяц, переплата около 590 тысяч. Дифференцированный: первый платёж около 33 тысяч, последний — около 17, переплата около 508 тысяч. Разница больше 80 тысяч, но в первые месяцы дифференцированный платёж заметно тяжелее.'],
 ['Досрочное погашение','При досрочном платеже банк обычно предлагает выбор: уменьшить срок или уменьшить платёж. Уменьшение срока экономит больше процентов, уменьшение платежа снижает нагрузку. Если платёж комфортный, выбирай сокращение срока.'],
 ['Что проверить в договоре','Есть ли комиссия за досрочное погашение, с какого числа считается платёж, как быстро банк пересчитывает график. И главное — полная стоимость кредита: эффективная ставка со всеми платежами и комиссиями, а не рекламная.']],
cushion:[['Зачем она нужна','Подушка превращает неприятность в неудобство. Сломалась машина, задержали зарплату, заболел — без запаса приходится брать кредит под высокий процент, а с запасом ты берёшь деньги со своего счёта и спокойно восстанавливаешь его.'],
 ['Не путать с накоплениями','Подушка — не деньги на отпуск или машину. Её не трогают ради покупок, только при настоящем ЧП. Взял — первым делом пополни обратно. Удобно держать её на отдельном счёте, который не мелькает в повседневном приложении.'],
 ['Сколько точно','Посчитай обязательные расходы за месяц: жильё, коммунальные, еда, кредиты, связь, транспорт. Умножь на три — это минимум. Если доход нестабильный, семья большая или ты единственный, кто зарабатывает, ориентир — шесть месяцев и больше.']],
compound:[['Время важнее суммы','Двое откладывают по десять тысяч в месяц под одинаковые 8 % годовых. Первый начинает в 25 лет и через 10 лет перестаёт. Второй начинает в 35 и откладывает 30 лет. К 65 годам у первого окажется больше денег, хотя внёс он втрое меньше: его деньги дольше работали.'],
 ['Ставка против инфляции','Сложный процент работает на реальные деньги, только когда доходность выше инфляции. Десять процентов при инфляции в девять — это около процента реального роста. Смотри не на красивую ставку, а на разницу между ней и ростом цен.'],
 ['Как начать','Не жди идеального момента и большой суммы. Настрой автоматический перевод в день зарплаты, пусть небольшой, и увеличивай его с каждым повышением дохода. Через несколько лет проценты начнут приносить заметные деньги.']],
starlings:[['Зачем им стая','Огромная стая защищает от хищников: соколу трудно выбрать одну птицу в мелькающем облаке. Чем плотнее и подвижнее стая, тем больше шансов у каждого. Поэтому скворцы особенно активно «танцуют», когда рядом хищник.'],
 ['Мурмурация','Танец скворцов по-английски называют мурмурацией — от шороха тысяч крыльев. Его можно увидеть осенью и зимой на закате, перед тем как птицы садятся на ночёвку в тростники или деревья. Иногда в одной стае сотни тысяч птиц.'],
 ['Правило ближайших соседей','Модель «каждый следит за несколькими ближайшими» работает и у людей: в толпе, в пробке, в команде. Хорошая команда — не та, где все смотрят на начальника, а та, где каждый внимателен к тем, кто рядом, и быстро передаёт сигнал дальше.']],
ice:[['Лёд для разного спорта','Для хоккея лёд делают холоднее и твёрже, для фигурного катания — чуть теплее и мягче, чтобы лезвие лучше врезалось при прыжках. Разница всего в несколько градусов, но спортсмены её чувствуют.'],
 ['Песок и соль','Песок и гранитная крошка не растапливают лёд, а создают шершавые точки опоры. Соль работает иначе: она понижает температуру замерзания воды, и при небольшом морозе лёд превращается в слякоть. При сильном морозе соль почти бесполезна.'],
 ['Как ходить по льду','Ставь ногу на всю стопу, шагай коротко, держи центр тяжести над ногами, а руки — свободными, не в карманах. Если падаешь, старайся упасть на бок и сгруппироваться, а не выставлять прямую руку: так чаще всего ломают запястье.']],
salmon:[['Путь вверх по реке','На нерест лосось идёт против течения и прыгает через пороги и водопады. Многие тихоокеанские лососи в реке перестают есть и после нереста погибают. Их тела становятся пищей для медведей и птиц и удобрением для прибрежного леса.'],
 ['Медведи и лес','Медведи вытаскивают рыбу на берег и оставляют остатки. Учёные находили в деревьях у нерестовых рек азот морского происхождения — питательные вещества, которые лосось принёс из океана. Получается, что лес у реки отчасти растёт благодаря рыбе.'],
 ['Что взять себе','Лосось пользуется разными инструментами на разных этапах: магнитным компасом в океане и обонянием у дома. Так и в больших целях: на старте нужен общий курс, а ближе к финишу — внимание к деталям.']],
gps:[['Сколько нужно спутников','Чтобы определить место, приёмнику нужны сигналы минимум от четырёх спутников: три дают координаты, четвёртый нужен, чтобы поправить неточные часы самого телефона. Поэтому между высокими домами точность падает — часть спутников закрыта.'],
 ['Не только GPS','Американская GPS — не единственная система. Есть российская ГЛОНАСС, европейская Galileo и китайская BeiDou. Современный телефон принимает сигналы всех сразу, и это ускоряет определение места и повышает точность.'],
 ['Как приложение считает километры','Фитнес-приложение складывает отрезки между точками GPS. Если сигнал прыгает, трек получается зубчатым и дистанция завышается; если точек мало — срезаются повороты. Поэтому в парке под открытым небом километры точнее, чем между домами.']],
echo:[['Как нашли «Титаник»','Обломки «Титаника» в 1985 году нашли с помощью буксируемого гидролокатора и подводных камер на глубине около 3 800 метров. Звук — единственный способ «видеть» на таких глубинах: свет пропадает уже через несколько сотен метров.'],
 ['Рыбаки и эхолот','Рыболовный эхолот показывает не только дно, но и рыбу: плавательный пузырь с газом хорошо отражает звук. Опытный рыбак по форме отметок отличает стаю мелочи от крупной одиночной рыбы.'],
 ['Летучие мыши','Летучая мышь издаёт ультразвуковые крики десятки раз в секунду, а при атаке на насекомое — до двухсот раз. По эху она понимает расстояние, размер и направление полёта добычи. Некоторые бабочки в ответ научились сбивать её сигналы своими щелчками.']],
battery:[['Почему жара вредна','Внутри аккумулятора идут химические реакции, и при нагреве они ускоряются — в том числе те, что разрушают электроды. Телефон на панели машины летом может нагреться до 50–60 градусов, и за одно такое лето батарея теряет заметную часть ёмкости.'],
 ['Быстрая зарядка','Быстрая зарядка сама по себе не губит аккумулятор: телефон управляет током и замедляется после 70–80 процентов. Но она сильнее греет батарею, поэтому не заряжай быстро в чехле под подушкой или на солнце. Ночью лучше обычная зарядка с оптимизацией.'],
 ['Когда менять','Если телефон к вечеру садится заметно быстрее, чем в первый год, проверь состояние батареи в настройках. При ёмкости ниже 80 процентов замена аккумулятора обычно дешевле и разумнее нового телефона.']],
negatives:[['Почему негативы работают','В уступающей фазе — когда опускаешься — мышцы способны выдержать больше, чем поднять. Медленное опускание даёт им нагрузку, близкую к подтягиванию, но посильную. Заодно ты учишься держать лопатки и корпус — это пригодится в настоящем подтягивании.'],
 ['Хват и вис','Начни с простого виса: 20–30 секунд на прямых руках, лопатки опущены. Это укрепляет хват и плечи. Хват на ширине плеч ладонями к себе обычно даётся легче, чем широкий ладонями от себя, — с него удобно начинать.'],
 ['Как не застрять','Если прогресс встал, добавь упражнения на спину — тягу гантели в наклоне, подтягивания с резинкой — и следи за весом. Каждый лишний килограмм — дополнительная нагрузка в каждом повторе.']],
sleep:[['Что происходит ночью','Сон состоит из циклов примерно по полтора часа. В глубоком сне восстанавливаются ткани, в быстром мозг перерабатывает впечатления и закрепляет навыки, в том числе двигательные. Поэтому техника, которую ты учил днём, к утру становится твёрже.'],
 ['Свет и кофе','Яркий экран вечером сдвигает внутренние часы, а кофеин держится долго: через пять–шесть часов в крови остаётся около половины. Чашка кофе в четыре дня может мешать заснуть в одиннадцать.'],
 ['Ритуал отхода ко сну','Одинаковое время отбоя, прохладная тёмная комната, телефон вне кровати, тёплый душ и несколько страниц бумажной книги. Через неделю–две тело начинает засыпать по сигналу, как по расписанию.']],
return:[['Разговор о главном','Через несколько дней после возвращения стоит спокойно поговорить: что было трудно, пока тебя не было, что получилось хорошо, что хочется изменить. Слушай больше, чем говоришь. Человек, который держал дом, часто ждёт не помощи, а признания.'],
 ['Дети','Дети по-разному встречают возвращение: кто-то бросается на шею, кто-то обижается и держит дистанцию. Это нормально. Не дави, будь рядом и предлагай общие занятия — прогулку, игру, поездку. Через несколько дней всё встанет на место.'],
 ['Свой ритм','Тебе тоже нужно время перестроиться. Не планируй на первые дни много встреч и дел. Сон, прогулки, простые домашние занятия помогают вернуться домой не только телом, но и головой.']],
kroc:[['Система важнее блюда','Крок не придумал бургер — он придумал, как сделать, чтобы в любом ресторане сети он был одинаковым. Для этого появились подробные инструкции, а в 1961 году — учебный центр для управляющих, который назвали «Гамбургерным университетом».'],
 ['Спорная сторона','Отношения с братьями Макдональд закончились плохо: после сделки они не могли использовать собственную фамилию для своего первого ресторана, а Крок открыл рядом конкурирующую точку. Эта история — напоминание, как важно читать договор до подписи.'],
 ['Поздний старт','Главное дело жизни Крок начал после пятидесяти, имея проблемы со здоровьем. Он говорил, что лучшее у него впереди. Это не значит, что все добиваются успеха поздно, но значит, что возраст — не причина не начинать.']],
knight:[['Вафельница','Бауэрман был одержим лёгкостью: он считал, что лишние граммы в обуви за забег превращаются в огромный поднятый вес. Он сам шил кроссовки для своих бегунов. Подошва из вафельницы — символ того, что инженерная мысль может родиться на кухне.'],
 ['Имя','Название Nike — в честь греческой богини победы — предложил первый сотрудник компании Джефф Джонсон; по его словам, имя пришло ему во сне. Найт сомневался, но времени на раздумья не было: обувь уже нужно было маркировать.'],
 ['Урок','История Nike — о том, что дело растёт из страсти: Найт и Бауэрман сами были бегунами и делали обувь для таких же людей. И о том, что долгие годы без денег — нормальная часть пути, а не знак, что пора сдаться.']],
dyson:[['Почему циклон','Мешковый пылесос теряет тягу, потому что мелкая пыль забивает поры мешка. Циклон раскручивает воздух: тяжёлые частицы отбрасываются к стенкам и падают в контейнер, а воздух идёт дальше почти без сопротивления. Тяга не падает, пока контейнер не переполнен.'],
 ['Суды','Когда идею Дайсона скопировала крупная компания, он судился несколько лет и выиграл. Деньги на патенты и юристов он брал в долг, рискуя всем. Защищать изобретение оказалось почти так же трудно, как его создать.'],
 ['Метод прототипов','Дайсон меняет одну вещь за раз и смотрит, что получится, — так понятно, что именно улучшило результат. Метод подходит и к тренировкам: поменяй одно упражнение или режим и посмотри, что изменилось через две недели.']],
ortega:[['Логистика как оружие','Значительная часть производства и главный склад Inditex находятся в Испании, рядом со штаб-квартирой, а не в дальних странах, как у многих конкурентов. Шить там дороже, но дешевле ошибаться: новая модель быстро попадает в магазины, а то, что не продаётся, быстро снимают.'],
 ['Мало, но часто','Магазины получают новые поставки дважды в неделю, а каждой модели выпускают немного. Покупатели знают: понравилось — бери сейчас, завтра может не быть. Это приучает заходить в магазин часто.'],
 ['Тихий лидер','Ортега почти не появлялся на публике — до конца девяностых не было даже его официальных фотографий. Он считал, что лицо компании — её магазины, а не владелец.']],
transsib:[['Как строили','На стройке работали десятки тысяч человек: крестьяне, солдаты, ссыльные, рабочие из других стран. Многое делали вручную — лопатами и тачками. В вечной мерзлоте и на болотах приходилось придумывать новые способы укладки пути.'],
 ['Мост через Енисей','Мост через Енисей у Красноярска получил золотую медаль на Всемирной выставке в Париже в 1900 году — той самой, где показывали Эйфелеву башню как символ инженерного века. Его пролёты собирали над рекой без современной техники.'],
 ['Дорога сегодня','Поезд Москва — Владивосток идёт около недели и пересекает семь часовых поясов. По Транссибу везут грузы из Азии в Европу, а для многих сибирских городов он до сих пор главная связь со страной.']],
apollo13:[['«Хьюстон, у нас проблема»','Знаменитая фраза на самом деле звучала чуть иначе: «Хьюстон, у нас была проблема». Сначала о неполадке доложил пилот Джек Суайгерт, потом повторил командир Джим Ловелл. Голоса были спокойными: паника в такой ситуации — роскошь.'],
 ['Работа на Земле','В центре управления инженеры работали посменно, круглые сутки. Каждую процедуру сначала проверяли на тренажёрах и только потом передавали экипажу. Задача была одна — вернуть людей домой, и все решения подчинялись ей.'],
 ['Урок','Когда план рухнул, главное — быстро поменять цель и собрать решение из того, что есть. «Аполлон-13» не сел на Луну, но показал, как работает команда, которая заранее отрепетировала множество неприятностей.']],
wing:[['Почему птицы машут','Взмахи крыльев дают птице и подъёмную силу, и тягу вперёд. Крупные птицы — орлы, аисты — много парят в восходящих потоках тёплого воздуха, почти не тратя сил, как планер.'],
 ['Полёт вверх ногами','Пилотажные самолёты летают вверх колёсами, потому что подъёмная сила зависит прежде всего от угла атаки. Перевернув самолёт, пилот ставит крыло под нужным углом к потоку — и оно снова держит машину.'],
 ['Ложка под краном','Поднеси ложку выпуклой стороной к струе воды — её затянет в струю. Поток огибает выпуклость и отклоняется, а ложку тянет в обратную сторону. Это хорошая домашняя модель того, что происходит у крыла.']],
tacoma:[['Видео на века','Обрушение снял на плёнку владелец местного фотомагазина. Эти кадры до сих пор показывают будущим инженерам как пример того, что расчёта на прочность мало: нужно понимать, как конструкция ведёт себя в потоке воздуха.'],
 ['Резонанс и флаттер','Резонанс — когда внешняя сила раскачивает систему в такт её собственным колебаниям, как ребёнка на качелях. Флаттер хитрее: конструкция сама меняет поток вокруг себя, и колебания подпитывают друг друга. Он опасен для мостов, крыльев и лопастей.'],
 ['Где ещё это важно','Тот же эффект учитывают при проектировании высоток, дымовых труб и линий электропередачи. На проводах ЛЭП можно увидеть небольшие грузики — это гасители вибрации, которые не дают ветру раскачать провод.']],
pascal:[['Блез Паскаль','Закон назван в честь французского учёного XVII века Блеза Паскаля. В девятнадцать лет он построил механическую счётную машину, чтобы помочь отцу со сбором налогов, а позже ставил опыты с давлением воздуха и жидкостей.'],
 ['Тормоза','В тормозной системе машины жидкость передаёт усилие от педали к колёсам. Если в неё попал воздух, педаль становится «ватной»: воздух сжимается, и давление не доходит до колодок. Поэтому систему прокачивают и меняют жидкость по регламенту.'],
 ['Рычаги в теле','Обмен силы на расстояние есть и в нашем теле, только наоборот: мышцы крепятся близко к суставу и выигрывают в скорости движения ценой большого усилия. Поэтому длина рук и ног влияет на то, какие упражнения даются легче.']],
cloud:[['Виды облаков','Кучевые — пухлые, с плоским основанием — появляются в солнечные дни. Слоистые — серая пелена, из которой моросит. Перистые — высокие ледяные нити, часто предвестник смены погоды. По облакам можно предсказать погоду на несколько часов вперёд.'],
 ['Как растёт гроза','Кучевое облако становится грозовым, когда тёплый влажный воздух поднимается очень высоко — до десяти километров и выше. Наверху капли замерзают, частицы льда сталкиваются и электризуются. Отсюда молнии и град.'],
 ['Что делать в грозу','Если гроза застала на открытом месте, уходи с возвышенностей, не стой под одиноким деревом, держись подальше от воды. Число секунд между вспышкой и громом, делённое на три, — примерное расстояние до грозы в километрах.']],
sky:[['Почему облака белые','Капли в облаках намного крупнее молекул воздуха и рассеивают все цвета одинаково. Поэтому облака белые, а толстые — серые: свет просто не проходит сквозь них насквозь.'],
 ['Небо на Марсе','На Марсе всё наоборот: днём небо желтовато-рыжее из-за пыли, а закаты голубоватые. Мелкая пыль рассеивает свет иначе, чем молекулы земного воздуха.'],
 ['Голубые горы','Далёкие горы и леса кажутся голубоватыми по той же причине: между тобой и ними много воздуха, и он подмешивает рассеянный синий свет. Художники используют это, чтобы показать глубину на картине.']],
ants:[['Муравейник','Муравейник — не куча хвои, а сложная постройка с вентиляцией, камерами для личинок и кладовыми. Его температуру регулируют: муравьи открывают и закрывают ходы и переносят личинок в тёплые или прохладные места.'],
 ['Сила муравья','Муравей поднимает груз, во много раз тяжелее себя. Секрет не в особых мышцах, а в размере: у маленького тела мышцы относительно сильнее по отношению к его массе.'],
 ['Урок для команды','Колония справляется без начальника, потому что у каждого есть простое правило и быстрая обратная связь. В команде это тоже работает: понятные правила, видимый результат каждого и готовность забывать то, что больше не работает.']],
frigate:[['Как они охотятся','Фрегаты хватают рыбу у поверхности на лету — особенно летучих рыб, выпрыгивающих из воды. Ещё они известны тем, что отбирают добычу у других морских птиц, преследуя их в воздухе. За это их называют пиратами.'],
 ['Огромные крылья','Размах крыльев фрегата больше двух метров при весе около полутора килограммов. Такое соотношение позволяет часами парить, почти не взмахивая крыльями, и пользоваться восходящими потоками под облаками.'],
 ['Урок о сне','Даже птицы, которые умеют спать на лету, при первой возможности отсыпаются. Короткие урывки помогают продержаться, но не заменяют нормального сна. Человеку — тем более.']],
rule50:[['Пример','Доход 300 тысяч. 150 — обязательные расходы, 90 — желания, 60 — сразу на отдельный счёт. Через год это 720 тысяч, которые не растворились в мелких тратах.'],
 ['Если долгов много','Пока есть дорогие кредиты, «двадцать процентов на будущее» разумно направлять на их досрочное погашение, начиная с самого дорогого. Это тоже вклад в будущее: погашенная тысяча перестаёт приносить проценты банку.'],
 ['Пересматривай раз в квартал','Доходы и расходы меняются. Раз в три месяца сравни, как реально распределились деньги, и поправь лимиты. Правило — не клетка, а ориентир.']],
grace:[['Кэшбэк и ловушки','Банки дают кэшбэк, чтобы ты чаще пользовался картой. Это выгодно, только если ты не тратишь больше обычного ради баллов. Покупка ради кэшбэка — классическая ловушка.'],
 ['Автоплатёж','Самый надёжный способ не пропустить дату — автоплатёж на всю сумму задолженности за день до конца льготного периода. Тогда забывчивость не превратится в проценты.'],
 ['Когда кредитка не нужна','Если ты замечаешь, что по кредитке тратишь больше, чем по обычной карте, или постоянно не успеваешь погасить долг, — закрой её. Никакой кэшбэк не окупит проценты.']],
inflation:[['Откуда взялось 72','Число 72 удобно, потому что делится на многие числа: 2, 3, 4, 6, 8, 9, 12. Точная формула сложнее, но при ставках от 6 до 10 процентов правило ошибается совсем немного.'],
 ['Правило и долги','Долг под 24 % годовых, который не гасится, удваивается примерно за три года. Хорошая причина гасить дорогие кредиты в первую очередь.'],
 ['Личная инфляция','Официальная инфляция — среднее по корзине товаров. Твоя может быть выше или ниже: если ты много тратишь на то, что дорожает быстрее, денег будет хватать меньше, чем показывает статистика.']],
terry:[['Протез','Терри бежал на простом протезе, не рассчитанном на марафонские нагрузки, — особым шагом: подскок на здоровой ноге и шаг на протезе. Культя натиралась до крови, но он продолжал.'],
 ['Поддержка','Рядом ехал фургон с другом детства Дугом Алвардом, позже к ним присоединился брат Терри Даррелл. В городках его встречали жители, полицейские, школьники. В Торонто на площади собрались тысячи людей.'],
 ['Наследие','Каждый год по всему миру проходят забеги Терри Фокса. В них нет победителей и призов — только дистанция и сбор средств на исследования рака. Канадцы до сих пор называют его одним из величайших людей своей страны.']],
pushups:[['Техника','Тело — прямая линия от пяток до макушки, руки чуть шире плеч, локти примерно под 45 градусов к корпусу. Опускайся, пока грудь почти не коснётся пола, и выжимай вверх без прогиба в пояснице. Десять хороших повторений полезнее двадцати плохих.'],
 ['Если не получается ни одного','Начни с отжиманий от стены, потом от стола, потом от низкой скамьи. Чем ниже опора, тем тяжелее. Отжимания с колен тоже работают — главное, чтобы корпус оставался прямым.'],
 ['Разнообразие','Когда пятьдесят будет близко, добавляй варианты: узкие отжимания на трицепс, с паузой внизу, с ногами на возвышении. Мышцам нужна новая нагрузка, иначе прогресс замедляется.']],
talktest:[['Почему медленно — это быстро','Выносливость растёт от длительной лёгкой работы: в мышцах становится больше капилляров и митохондрий, сердце выбрасывает больше крови за удар. Быстрые тренировки нужны, но в небольшой доле — обычно не больше пятой части всего бега.'],
 ['Где бегать','Грунтовые и парковые дорожки бережнее к суставам, чем асфальт. Но главное — регулярность: лучше бегать по асфальту трижды в неделю, чем раз в месяц по идеальной трассе.'],
 ['Признаки перегруза','Утренний пульс выше обычного, плохой сон, тяжёлые ноги несколько дней подряд, боль, которая усиливается на бегу, — сигналы снизить нагрузку. Отдых — часть тренировки, а не её пропуск.']],
quarrel:[['Я-сообщения','Вместо «ты всегда опаздываешь» скажи «я волнуюсь, когда не знаю, где ты». Фраза о своих чувствах не нападает, и на неё легче ответить без обороны.'],
 ['Одна тема за раз','Ссоры разгораются, когда в одну кучу сваливают всё — и вчерашнее, и прошлогоднее. Договоритесь обсуждать один вопрос. Остальное — в другой раз.'],
 ['Мириться','Важно не только остановить ссору, но и вернуться друг к другу: обнять, сказать «хорошо, что мы поговорили», сделать что-то вместе. Это укрепляет отношения сильнее, чем отсутствие конфликтов.']],
gifts:[['Подарок-впечатление','Исследования счастья показывают: впечатления часто радуют дольше вещей. Билет на концерт, поездка, мастер-класс, совместный день — хороший выбор, когда не знаешь, что подарить.'],
 ['Своими руками','Письмо, фотоальбом, видео от друзей, отремонтированная вещь — такие подарки ценят за потраченное время. Для родителей, бабушек и дедушек это часто лучший вариант.'],
 ['Как не ошибиться','Сомневаешься — спроси прямо или посоветуйся с близкими человека. Сюрприз хорош, когда попадает в цель. Подарок, который будет пылиться, — не сюрприз, а проблема.']],
parents:[['Видеозвонок','Если родители освоили видеосвязь, покажи им свою жизнь: кухню, прогулку, внуков, что готовишь. Им важно видеть, а не только слышать. Терпеливо помоги настроить телефон — это тоже забота.'],
 ['Записывай истории','Рассказы родителей можно записывать на диктофон — с их согласия. Через годы эти записи станут бесценными для тебя и твоих детей. Хорошие вопросы: где ты рос, кем мечтал стать, как вы познакомились.'],
 ['Не только звонки','Открытка по почте, посылка с мелочами, напечатанные на бумаге фото внуков — пожилые люди особенно ценят то, что можно подержать в руках.']]};
READ_PACK.forEach(m=>{if(!m.full&&READ_FULL[m.id])m.full=READ_FULL[m.id]});
const READ_FULL2={
ford:[['Цифры','К 1927 году, когда выпуск «Модели Т» остановили, её сделали больше 15 миллионов штук. Одно время каждый второй автомобиль в США был «Фордом». Сборка одной машины в лучшие годы занимала около полутора часов, а с конвейера сходило по машине каждые десять секунд.'],
 ['Что взять себе','Принцип Форда работает в любом деле: разбей большую задачу на простые повторяемые шаги и убери всё лишнее. Хочешь каждый день отжиматься — не составляй сложную программу, а сделай одно движение настолько простым, чтобы его невозможно было пропустить: три подхода сразу после чистки зубов.']],
shackleton:[['Цифры','Экспедиция длилась почти два года — с августа 1914 по август 1916-го. «Эндьюранс» дрейфовал во льдах около десяти месяцев. Шлюпка «Джеймс Кэрд» была длиной меньше семи метров, а плавание на ней называют одним из величайших в истории мореходства.'],
 ['Что взять себе','Когда план рушится, Шеклтон не цеплялся за старую цель, а честно поменял её на ту, что важнее. Он держал людей занятыми, не позволял распасться режиму дня и сам брал худшее. Если у тебя трудный период — сначала сохрани распорядок: подъём, еда, движение, сон. Он вытащит остальное.']],
honda:[['Цифры','Super Cub выпускается с 1958 года и считается самым массовым моторным транспортом в истории — их выпущено больше ста миллионов. Honda стала крупнейшим в мире производителем мотоциклов, а позже вышла и на рынок автомобилей.'],
 ['Что взять себе','Хонда считал, что неудачи — это 99 процентов работы, а успех — оставшийся один. Он не стыдился ошибок, а изучал их. Если что-то не получилось — запиши, почему, и поменяй одно условие. Так делают инженеры, и так растёт любой навык.']],
kamprad:[['Цифры','Первый магазин IKEA открылся в 1958 году в Эльмхульте. Сегодня у компании сотни магазинов в десятках стран, а её каталог когда-то печатали тиражом в сотни миллионов экземпляров — больше, чем многие самые известные книги.'],
 ['Что взять себе','Плоская упаковка — пример того, как одна мелочь меняет весь процесс: дешевле доставка, меньше склад, ниже цена. Посмотри на свои дела: что можно «сложить плоско»? Например, собрать спортивную сумку с вечера, чтобы утром не искать вещи и не пропускать тренировку.']],
korolev:[['Цифры','Ракета Р-7 весила около 280 тонн на старте. Первый спутник весил всего 83,6 килограмма и передавал простой радиосигнал «бип-бип», который ловили радиолюбители по всему миру. Через три с половиной года на ракете того же семейства полетел Гагарин.'],
 ['Что взять себе','Королёв пережил арест и лагерь, но не позволил несправедливости остановить своё дело. Его пример — о том, что большая цель помогает пройти через тяжёлые времена. Держи в голове то, ради чего ты стараешься, — особенно в дни, когда всё идёт плохо.']],
konyukhov:[['Цифры','Список экспедиций Конюхова огромен: несколько кругосветных плаваний под парусом, восхождения на высочайшие вершины всех континентов, переходы к Северному и Южному полюсам, переходы через океаны на вёсельной лодке и рекордный облёт Земли на воздушном шаре.'],
 ['Не только путешественник','Конюхов пишет картины и книги о своих походах, а в 2010 году стал священником. Он говорит, что в долгом одиночном плавании важнее всего не мышцы, а голова: режим дня, работа руками и умение не паниковать, когда что-то идёт не так.']],
amundsen:[['Цифры','Норвежцы прошли путь к полюсу и обратно — около трёх тысяч километров — за 99 дней. Амундсен взял 52 собаки, а вернулся с 11: остальные стали частью тщательно рассчитанного плана снабжения.'],
 ['Что взять себе','Амундсен говорил, что победа ждёт того, у кого всё в порядке, — и это называют удачей. На деле его «удача» — это подготовка: правильная одежда, проверенный транспорт, запас и ровный темп. Готовься к своим целям так же: проверь снаряжение, рассчитай силы, иди без рывков.']],
magellan:[['Цифры','Из примерно 270 человек, вышедших в плавание, в Испанию на «Виктории» вернулись восемнадцать. Путь занял почти три года. Экспедиция доказала, что Землю можно обогнуть, и показала её настоящие размеры — океан оказался куда больше, чем думали.'],
 ['Что взять себе','Великие открытия редко бывают гладкими. Экспедиция Магеллана пережила бунт, голод и гибель капитана — и всё равно завершила путь. Если твой план идёт с потерями, это не обязательно провал. Важно, чтобы кто-то довёл дело до конца.']],
bering:[['Цифры','Великая Северная экспедиция длилась с 1733 по 1743 год. Её отряды описали тысячи километров побережья от Белого моря до Чукотки и составили карты, которыми пользовались больше века.'],
 ['Что взять себе','Беринг не дожил до конца экспедиции, но его команда построила новое судно из обломков старого и вернулась домой. Даже если дела идут плохо, можно собрать что-то из того, что осталось. Не выбрасывай опыт неудачи — из него строится следующая попытка.']],
lock:[['Интересно','Самые древние шлюзы с воротами строили в Китае больше тысячи лет назад. В Европе похожие сооружения появились в Средние века, а одну из конструкций ворот, которая до сих пор используется во многих шлюзах, приписывают Леонардо да Винчи.'],
 ['Шлюз на Иртыше','В Казахстане тоже есть знаменитый шлюз — Усть-Каменогорский на Иртыше. Он поднимает суда примерно на сорок метров в одной камере и считается одним из самых высоких однокамерных шлюзов в мире. После долгого ремонта его снова открыли для судов в 2015 году.']],
squat:[['Интересно','Проседание на мелководье учитывают и при проектировании портов: глубину каналов рассчитывают с запасом под килём с учётом скорости и размера судов. Из-за этого крупные суда идут в узостях медленнее, чем могут.'],
 ['Скорость в квадрате','Штурманы используют простое правило: проседание растёт примерно пропорционально квадрату скорости. Если идти вдвое быстрее, судно сядет глубже почти в четыре раза. Поэтому на мелководье даже небольшое снижение скорости даёт большой запас под килём.']],
antifouling:[['Интересно','Ракушки, которые прилипают к корпусам, держатся на особом клее — одном из самых прочных природных клеев. Учёные изучают его, чтобы создать медицинский клей, который работал бы во влажной среде.'],
 ['Сколько это стоит','Даже тонкий слой слизи на корпусе увеличивает сопротивление воды, а сильное обрастание ракушками может поднять расход топлива на десятки процентов. Для большого судна это тонны лишнего топлива в сутки — поэтому чистка и покраска окупаются быстро.']],
annuity:[['Частые ошибки','Брать кредит, глядя только на ежемесячный платёж: банк легко сделает его маленьким за счёт длинного срока, и переплата вырастет. Второе — не читать о страховке: её часто включают в сумму кредита, и проценты начисляются и на неё тоже.'],
 ['Попробуй сегодня','Если у тебя есть кредит, найди в приложении банка график платежей и посмотри, сколько процентов ты заплатишь всего. Затем посчитай, сколько сэкономит даже небольшой досрочный платёж в этом месяце. Это займёт десять минут и может сберечь тысячи.']],
cushion:[['Частые ошибки','Держать подушку на карте, которой платишь каждый день, — деньги незаметно растворяются в покупках. Вкладывать её в рискованные активы — в плохой момент она может подешеветь именно тогда, когда понадобится. И собирать «потом, когда будет больше зарплата» — такое «потом» обычно не наступает.'],
 ['Попробуй сегодня','Открой отдельный накопительный счёт и переведи туда любую сумму — даже символическую. Настрой автоперевод в день зарплаты. Через месяц ты удивишься, как легко копится то, что уходит до того, как ты успел это потратить.']],
compound:[['Частые ошибки','Ждать «правильного момента», чтобы начать откладывать. Забирать проценты, вместо того чтобы оставлять их работать. И путать доходность с гарантией: высокий процент почти всегда означает высокий риск.'],
 ['Попробуй сегодня','Открой любой онлайн-калькулятор сложных процентов и посчитай, во что превратится твоя ежемесячная сумма через 10 и 20 лет. Увидеть свои цифры — сильная мотивация не откладывать начало.']],
starlings:[['Интересно','Похожие правила используют инженеры, которые учат стаи дронов летать вместе: каждый дрон следит за соседями, и группа движется как одно целое без единого командира. Те же принципы применяют в моделях движения толпы и транспорта.'],
 ['Что взять себе','Ты тоже часть «стаи»: привычки друзей и близких влияют на твои, а твои — на их. Найди пару людей, которые тренируются или читают, и держись рядом — их ритм незаметно подтянет и тебя. Поэтому вызовы друзьям работают лучше, чем обещания себе.']],
ice:[['Интересно','Скольжение лыж и коньков связано не только с жидким слоем, но и с трением: оно немного подогревает поверхность. Поэтому смазку для лыж подбирают по температуре снега — при разном морозе работает разная смазка.'],
 ['Что взять себе','Самый опасный лёд — около нуля, когда снаружи он кажется безобидным. Так и в жизни: опасность часто прячется не в очевидно тяжёлых ситуациях, а в «почти нормальных». Будь внимательнее, когда всё кажется простым.']],
salmon:[['Интересно','Молодые лососи могут несколько лет жить в реке, прежде чем уйти в море. В океане они проходят тысячи километров, а потом точно находят устье родной реки. Учёные до сих пор изучают, как именно им удаётся запоминать магнитные «координаты» дома.'],
 ['Рыбоходы','Плотины перегораживают реки, и лосось не может подняться к местам нереста. Поэтому на многих плотинах строят рыбоходы — лестницы из небольших бассейнов, по которым рыба поднимается ступенька за ступенькой. Без них в некоторых реках лосось бы исчез.']],
gps:[['Интересно','Спутники GPS летают на высоте около двадцати тысяч километров и делают оборот вокруг Земли примерно за полдня. Сигнал от них очень слабый — слабее, чем свет лампочки за тысячи километров, поэтому в помещении его так легко потерять.'],
 ['Что взять себе','GPS работает, потому что миллиарды маленьких поправок учтены заранее. В тренировках так же: маленькие ошибки в технике незаметны в одном повторении, но за месяц уводят далеко в сторону. Время от времени проверяй технику по видео или у тренера.']],
echo:[['Интересно','Скорость звука в воде больше чем в четыре раза выше, чем в воздухе. Киты используют это, чтобы общаться на огромных расстояниях: низкие звуки некоторых китов слышны за многие сотни километров.'],
 ['Что взять себе','Эхолот узнаёт о дне по отражённому сигналу. Так и мы узнаём о себе по обратной связи: записи в дневнике, цифры в приложении, мнение друзей. Не игнорируй «эхо» — оно показывает, где мелко, а где можно идти смелее.']],
battery:[['Частые ошибки','Оставлять телефон на зарядке на солнце или под подушкой. Полностью разряжать батарею «для калибровки» — для современных литиевых аккумуляторов это вредно. И пользоваться дешёвыми неоригинальными зарядками, которые могут перегревать аккумулятор.'],
 ['Попробуй сегодня','Зайди в настройки батареи телефона и включи оптимизированную зарядку или ограничение заряда, если оно есть. Проверь, сколько процентов ёмкости осталось у аккумулятора. Это пара минут, а телефон проживёт дольше.']],
negatives:[['План на месяц','Неделя 1–2: три раза в неделю по три подхода из пяти медленных опусканий и вис 20–30 секунд. Неделя 3: пробуй одно чистое подтягивание в начале тренировки, потом негативы. Неделя 4: подходы по одному подтягиванию с отдыхом минута–две, добивай негативами.'],
 ['Частые ошибки','Рывки и раскачка вместо подтягивания — так мышцы не учатся работать. Тренироваться каждый день до отказа — без отдыха сила не растёт. И бросать на второй неделе, когда кажется, что прогресса нет: первая сила приходит от нервной системы, и её почти не видно снаружи.']],
sleep:[['Частые ошибки','«Отсыпаться» в выходные до обеда — это сбивает внутренние часы, и в понедельник заснуть ещё труднее. Пить алкоголь «для сна» — он ухудшает глубокий сон. И ложиться с телефоном: яркий экран и бесконечная лента крадут по часу.'],
 ['Попробуй сегодня','Поставь будильник не на подъём, а на отбой — за полчаса до нужного времени сна. Когда он сработает, убери телефон и начни свой вечерний ритуал. Попробуй неделю — и сравни самочувствие.']]};
Object.assign(READ_FULL2,{
return:[['Тело и режим','После долгой дороги организм ещё живёт в старом ритме. Если сменился часовой пояс, выходи утром на улицу: дневной свет быстрее всего перестраивает внутренние часы. Днём спи не больше двадцати–тридцати минут, иначе ночь снова собьётся.'],
 ['Частые ошибки','Сразу забивать дни делами и гостями. Тратить много денег «на радостях» в первые выходные. Ждать, что все будут вести себя как раньше: близкие тоже изменились за это время. Лучше просто побыть рядом и послушать, как они жили.']],
kroc:[['Цифры','Первый ресторан, который открыл сам Крок, заработал в 1955 году в Де-Плейнсе под Чикаго. В 1961-м он открыл «Гамбургер-университет», где учили управлять ресторанами по единым правилам. Сегодня в сети больше сорока тысяч ресторанов в сотне с лишним стран.'],
 ['Что взять себе','Крок не придумал бургер — он увидел работающую систему и сделал её повторяемой. В тренировках и делах так же: не обязательно изобретать своё. Найди простой рабочий способ, который уже помогает другим, и повторяй его каждый день без пропусков.']],
knight:[['Мода на бег','Бауэрман сделал для бега не меньше, чем для обуви. В 1966 году он вместе с кардиологом Уэйном Харрисом выпустил книжку «Джоггинг» — её тираж перевалил за миллион. Американцы, которые раньше считали бег занятием спортсменов, стали выходить на пробежки, и спрос на кроссовки рос вместе с модой.'],
 ['Первые атлеты','Бауэрман тренировал бегунов Орегонского университета и проверял новые модели прямо на них. Одним из первых известных спортсменов в обуви Nike стал его ученик Стив Префонтейн — звезда американского бега начала 1970-х.']],
dyson:[['Первый успех','Британские производители отказывались брать изобретение. Первую лицензию купили в Японии: в 1986 году там продавали розовый циклонный пылесос G-Force — дорогую модную вещь. На эти деньги Дайсон открыл свою компанию, и в 1993 году вышел DC01, который за пару лет стал самым продаваемым пылесосом в Британии.'],
 ['Что взять себе','Каждый неудачный прототип Дайсон считал шагом вперёд: он менял одну деталь и смотрел, что получится. Это хороший способ улучшать что угодно — технику бега, бюджет, распорядок дня. Не переделывай всё сразу: поменяй одно и проверь результат.']],
ortega:[['Цифры','Первый магазин Zara открылся в 1975 году в Ла-Корунье. Сегодня Zara — часть группы Inditex, куда входят и другие известные марки одежды. Новая модель может пройти путь от эскиза до прилавка примерно за две-три недели, а магазины получают поставки по несколько раз в неделю.'],
 ['Что взять себе','Ортега слушал продавцов, а не только дизайнеров: что спрашивают, что не берут. Быстрая обратная связь важнее долгого планирования. Смотри на свои цифры каждую неделю — шаги, расходы, сон — и подстраивай план, а не жди конца года.']],
transsib:[['Цифры','От Москвы до Владивостока по Транссибу около девяти тысяч трёхсот километров, дорога пересекает восемь часовых поясов. Строительство начали в 1891 году и вели сразу с нескольких участков. Поезд «Россия» идёт по всему маршруту почти неделю.'],
 ['Байкал зимой','Самым трудным участком был обход Байкала по скалистому берегу. Пока его строили, вагоны переправляли через озеро на ледоколе-пароме. А зимой 1904 года, когда войска срочно перебрасывали на восток, рельсы положили прямо по льду и вагоны тянули лошадьми.']],
apollo13:[['Цифры','«Аполлон-13» стартовал 11 апреля 1970 года и вернулся на Землю 17 апреля. Экипаж — Джеймс Ловелл, Джон Суиджерт и Фред Хейз. Облетая Луну, они ушли от Земли дальше, чем кто-либо до них.'],
 ['Холод и экономия','Чтобы сберечь энергию для возвращения, командный модуль почти полностью выключили. Температура в кабине опустилась почти до нуля, воду строго делили, люди почти не спали. Хейз заболел, но экипаж держался: каждый знал, что любая лишняя трата — это шанс не вернуться.']],
wing:[['Угол атаки','Крыло ставят под небольшим углом к потоку. Оно отклоняет воздух вниз, а воздух в ответ толкает крыло вверх. Если угол становится слишком большим, поток срывается с верхней поверхности, подъёмная сила резко падает — это называется сваливанием. Пилотов специально учат его распознавать и выходить из него.'],
 ['Что взять себе','Простое объяснение не всегда верное, даже если его повторяют в учебниках. Если что-то в объяснении не сходится — например, как тогда самолёт летит вверх ногами, — задай вопрос и проверь. Это полезная привычка в любой теме: от здоровья до денег.']],
tacoma:[['Цифры','Мост открыли 1 июля 1940 года, а рухнул он 7 ноября — через четыре месяца. Центральный пролёт длиной около 850 метров был одним из самых длинных в мире. Ветер в тот день дул примерно 65 километров в час — не ураган. Из людей никто не погиб; в брошенной на мосту машине осталась собака.'],
 ['Что взять себе','Мост разрушила не сила ветра, а раскачка, которую никто не остановил вовремя. Маленькие повторяющиеся колебания опасны и для нас: недосып, лишние траты, пропуски тренировок. По отдельности мелочь, но когда они попадают в ритм, могут раскачать всё. Гаси их вовремя.']],
pascal:[['Гидравлика вокруг','Тот же закон поднимает ковш экскаватора, кресло в парикмахерской и машину на подъёмнике в автосервисе. Небольшой насос создаёт давление, а большой поршень превращает его в огромную силу. Поэтому одна гидравлическая машина заменяет десятки рабочих.'],
 ['Что взять себе','В механике нет бесплатного выигрыша: выигрываешь в силе — проигрываешь в расстоянии. Маленький поршень проходит длинный путь, чтобы большой поднялся чуть-чуть. Так и с целями: маленькое ежедневное усилие на длинной дистанции поднимает то, что рывком не сдвинуть.']],
cloud:[['Цифры','Обычное кучевое облако размером с километр в каждую сторону содержит примерно полграмма воды в каждом кубометре — в сумме сотни тонн, как несколько железнодорожных цистерн. Оно не падает, потому что капли крошечные: они опускаются очень медленно, а тёплый воздух снизу поднимает их обратно.'],
 ['Что взять себе','Облако — пример того, как огромная масса держится на множестве маленьких частей. Твои результаты тоже складываются из мелочей: десять минут чтения, стакан воды, короткая прогулка. Каждая почти ничего не весит, но вместе — целое облако.']],
sky:[['Почему не фиолетовое','Фиолетовый свет рассеивается ещё сильнее синего, так что небо, казалось бы, должно быть фиолетовым. Но в солнечном свете фиолетового меньше, а наши глаза к нему менее чувствительны. Смесь рассеянных цветов глаз воспринимает как голубой.'],
 ['Что взять себе','Цвет неба зависит от того, сквозь какую толщу воздуха идёт свет. Днём путь короткий — небо синее, вечером длинный — закат красный. Настроение тоже зависит от «толщины» дня: к вечеру всё кажется тяжелее. Важные решения и разговоры лучше переносить на утро.']],
ants:[['Муравьи и компьютеры','В 1992 году итальянский учёный Марко Дориго предложил «муравьиный алгоритм»: виртуальные муравьи ищут путь и оставляют цифровой след, а программа усиливает лучшие маршруты. Похожие методы применяют для планирования маршрутов доставки и сетей.'],
 ['Муравьи считают шаги','Пустынные муравьи находят дорогу к норе, считая шаги. Учёные проверили это смешным опытом: одним муравьям приклеили к ногам крошечные «ходули», другим укоротили ноги. Первые проскакивали мимо норы, вторые останавливались раньше — значит, путь они мерили шагами.']],
frigate:[['Как это узнали','В 2016 году учёные надели фрегатам над Галапагосскими островами крошечные датчики активности мозга. Оказалось, что в долгом полёте птицы спят меньше часа в сутки, короткими эпизодами по нескольку секунд, часто одним полушарием. На суше те же птицы спят по двенадцать часов.'],
 ['Другие рекордсмены','Чёрный стриж может не садиться почти десять месяцев: он ест, пьёт и спит в воздухе. Это тоже показали датчики, которые учёные прикрепили к птицам. Садятся стрижи в основном для того, чтобы вывести птенцов.']],
rule50:[['Откуда правило','Правило 50/30/20 популяризировали в 2005 году американский профессор Элизабет Уоррен и её дочь Амелия в книге о семейных финансах. Идея в том, чтобы не считать каждую покупку, а держать три больших ведра: обязательное, желания и будущее.'],
 ['Попробуй сегодня','Возьми свой доход за месяц и раздели на три части по этим процентам. Затем прикинь, сколько уходит на обязательное: жильё, кредиты, еду, транспорт. Если больше половины — не страшно, просто начни с малого: отложи хотя бы пять процентов в день зарплаты.']],
grace:[['Частые ошибки','Снимать наличные или переводить деньги с кредитки — на эти операции льготный период часто не действует, а комиссия большая. Вносить только минимальный платёж и думать, что льгота сохранится. Забывать, что период считается от даты, указанной в договоре, а не от дня покупки.'],
 ['Попробуй сегодня','Открой условия своей кредитной карты и найди три вещи: длину льготного периода, дату, до которой нужно погасить долг, и список операций, на которые льгота не распространяется. Поставь напоминание за три дня до даты платежа.']],
inflation:[['Примеры','Если цены растут на 8 % в год, они удваиваются примерно за девять лет. При 12 % — за шесть, при 4 % — за восемнадцать. Это значит, что деньги, лежащие под матрасом, при восьми процентах инфляции за девять лет теряют половину покупательной силы.'],
 ['Попробуй сегодня','Узнай текущую инфляцию в своей стране и ставку по своему вкладу или накопительному счёту. Если ставка ниже инфляции, деньги тают, хоть и медленнее, чем дома. Сравни несколько надёжных банков: разница в паре процентов за годы превращается в заметную сумму.']],
terry:[['Цифры','Терри начал 12 апреля 1980 года в Сент-Джонсе на атлантическом побережье Канады. За 143 дня он пробежал 5 373 километра и остановился 1 сентября у города Тандер-Бей: рак распространился на лёгкие. Терри умер 28 июня 1981 года, ему было двадцать два.'],
 ['Что взять себе','Терри не пытался пробежать всю страну сразу — он думал о следующем километре, следующем телеграфном столбе. Когда цель кажется огромной, сузь её до ближайшего шага. Сегодня — одна тренировка, одна запись, один подход. Остальное сложится.']],
pushups:[['План на месяц','Неделя 1: пять подходов по половине своего максимума через день. Неделя 2: добавь по одному-два повторения в каждый подход. Неделя 3: один подход до отказа в конце тренировки. Неделя 4: два дня отдыха и проверка максимума. Обычно результат растёт на треть и больше.'],
 ['Частые ошибки','Провисать в пояснице и задирать таз. Разводить локти в стороны под прямым углом — это нагружает плечи. Делать отжимания каждый день до отказа: мышцам нужен отдых. И считать только количество — десять чистых повторений лучше двадцати кривых.']],
talktest:[['План на месяц','Неделя 1: три тренировки по 20 минут — минута бега, две минуты шага. Неделя 2: две минуты бега, две шага. Неделя 3: три минуты бега, минута шага. Неделя 4: попробуй пробежать десять минут подряд в разговорном темпе. Если тяжело — повтори прошлую неделю.'],
 ['Обувь и одежда','Беговые кроссовки нужны с мягкой подошвой и по размеру: палец должен свободно помещаться перед носком. Одевайся так, будто на улице на десять градусов теплее — через пять минут бега разогреешься. Хлопок впитывает пот и холодит, синтетика сохнет быстрее.']],
quarrel:[['Почему двадцать минут','Психолог Джон Готтман заметил, что в ссоре пульс у людей часто поднимается выше ста ударов в минуту. В таком состоянии мозг хуже слышит собеседника и легче срывается. Чтобы тело успокоилось, нужно не меньше двадцати минут — и всё это время лучше не прокручивать обиды в голове, а отвлечься.'],
 ['Попробуй сегодня','Договорись с близким человеком о стоп-слове заранее, пока вы оба спокойны. Например: «Мне нужна пауза, вернусь через полчаса». Важно не уходить молча и обязательно вернуться к разговору — иначе пауза станет новой обидой.']],
gifts:[['Частые ошибки','Покупать в последний день — выбор маленький, цены высокие. Дарить то, что нравится тебе, а не человеку. Считать, что дорогой подарок исправит невнимание в течение года. И забывать про открытку: несколько тёплых слов от руки часто запоминаются дольше вещи.'],
 ['Попробуй сегодня','Создай в телефоне заметку «Подарки» и запиши туда пять близких людей. Под каждым — хотя бы одну вещь, о которой они упоминали за последний месяц. Добавь даты их дней рождения в календарь с напоминанием за неделю.']],
parents:[['Вопросы про запас','Что тебя сегодня порадовало? Как ты познакомился с мамой (или папой)? Какая была твоя первая работа? Чему ты научился у своих родителей? Какое блюдо из детства хотел бы снова попробовать? Такие вопросы превращают обычный звонок в разговор, который запоминается.'],
 ['Частые ошибки','Звонить только по делу или когда что-то случилось. Отвечать на расспросы односложно, торопясь положить трубку. Давать советы, о которых не просили. И откладывать звонок «до выходных», которые постоянно переносятся. Пять минут сегодня лучше часа когда-нибудь.']],
val:[['Память','Имя Валиханова носят Институт истории и этнологии в Алматы, университет в Кокшетау, улицы и школы по всему Казахстану. В урочище Кочен-Тоган у Алтын-Эмеля, где он умер, стоит мемориал. Его труды о Джунгарии, Кашгарии и казахских обычаях до сих пор изучают историки.']],
przh:[['Лошадь Пржевальского','Во время одной из экспедиций Пржевальскому подарили шкуру и череп дикой лошади, и по ним её описали как новый вид. В дикой природе она исчезла к концу 1960-х годов, но уцелела в зоопарках. Из этих животных вывели новые табуны и вернули их в степи Монголии, а позже — и в Оренбургский заповедник.']],
suvorov:[['«Наука побеждать»','Суворов написал наставление для солдат простым языком, короткими фразами, которые легко запомнить на марше: «Тяжело в учении — легко в походе», «Пуля обмишулится, штык не обмишулится», «Сам погибай, а товарища выручай». Он считал, что каждый воин должен понимать свой манёвр.']],
lego:[['Цифры','Название придумали из датских слов «leg godt» — «играй хорошо». Пластиковый кирпичик с трубками внутри, который крепко держится и легко снимается, запатентовали в 1958 году. Шесть кубиков 2×4 одного цвета можно соединить больше чем 915 миллионами способов.']],
toyota:[['От станков к машинам','Права на автоматический ткацкий станок Сакити продал британской компании, и эти деньги помогли его сыну Киитиро начать делать автомобили. Семейная фамилия — Тоёда, но марку назвали «Тойота»: слово звучало чище, а в японской записи занимало восемь черт, что считается счастливым числом.'],
 ['Кайдзен','Сакити всю жизнь улучшал одну машину — ткацкий станок, по шагу за раз. Японцы называют это «кайдзен» — постоянное маленькое улучшение. Попробуй каждую неделю улучшать одну мелочь: на минуту дольше планка, на сто рублей меньше лишних трат.']],
silk:[['Как путешествовали','Караваны шли от одного караван-сарая к другому — примерно на расстоянии дневного перехода, около тридцати–сорока километров. Мало кто проходил весь путь от Китая до Средиземноморья: товары передавали из рук в руки. Само название «Шёлковый путь» придумал немецкий географ Фердинанд фон Рихтгофен в 1877 году.']],
aral:[['Цифры','В 1960 году Арал был четвёртым по площади озером мира — около 68 тысяч квадратных километров. К 2000-м годам он распался на несколько водоёмов, а береговая линия у Аральска отступила на десятки километров. Кокаральскую плотину достроили в 2005 году, и Малый Арал снова начал подниматься.']],
camel:[['Цифры','Верблюд может выпить около сотни литров воды за несколько минут. Он переносит потерю воды до четверти веса тела — для человека опасны уже десять–пятнадцать процентов. Днём температура тела верблюда может подниматься на несколько градусов: так он меньше потеет, а ночью остывает.']],
boil:[['Тот же закон дома','Вода в чайнике на кухне в горном посёлке закипает быстрее, но остаётся прохладнее. Поэтому на высоте дольше варятся макароны, яйца и мясо, а пакеты с крупой иногда вздуваются — давление внутри больше, чем снаружи. По той же причине может «стрелять» шампунь, открытый в самолёте.']],
pulse:[['Когда идти к врачу','Если пульс в покое регулярно выше ста ударов или ниже пятидесяти без спортивной подготовки, если сердце «скачет» с перебоями, кружится голова или темнеет в глазах, — это повод показаться врачу. Часы могут подсказать, но диагноз ставит только специалист.']],
warmup:[['Почему это важно','Тёплые мышцы и связки эластичнее, а сердце и лёгкие успевают выйти на рабочий режим. Без разминки первые минуты тренировки даются тяжело, и выше риск потянуть мышцу. Пять минут — небольшая цена за то, чтобы тренироваться дольше и без травм.']],
water:[['Сколько на самом деле','Известное «восемь стаканов в день» — грубое правило, а не закон. Часть воды мы получаем с едой: супы, фрукты, овощи. Потребность зависит от жары, нагрузки и веса. Простой ориентир — светлая моча и отсутствие жажды. В жару и на тренировке пить нужно больше.']],
impulse:[['Попробуй сегодня','Заведи список «Хочу купить» в заметках. Всё, что захотелось купить спонтанно, записывай туда с датой. Через неделю посмотри: многие пункты покажутся лишними. А то, что осталось нужным, купишь спокойно и, может быть, дешевле.']],
bike:[['Частые ошибки','Покупать велосипед «на вырост» — на большом ребёнку страшно и неудобно. Долго бежать рядом, держа за руль: так ребёнок не чувствует равновесия. И заниматься, когда он устал или голоден. Пятнадцать минут в хорошем настроении лучше часа со слезами.']]
});
